def evaluate_rpn(rpn_tokens):
    """Evaluates a list of RPN tokens using a stack, performing exact arithmetic.

    Args:
        rpn_tokens: A list of tokens generated by the Shunting-Yard algorithm.

    Returns:
        The final result as a fractions.Fraction.

    Raises:
        CalcError: If a calculation error occurs (e.g., division by zero).
    """
    values = []

    for token in rpn_tokens:
        op_type = token['type']
        value = token['value']
        position = token['position']

        if op_type == 'number':
            # Convert string representation to Fraction exactly
            try:
                values.append(Fraction(value))
            except ValueError:
                # This should ideally not happen if tokenization is correct, 
                # but acts as a safeguard.
                raise CalcError(f"Invalid number format: {value}", position)

        elif op_type == 'operator':
            if value in ('+', '-', '*', '/'):
                if len(values) < 2:
                    raise CalcError("Insufficient operands for binary operator", position)

                operand2 = values.pop()
                operand1 = values.pop()

                if value == '+':
                    result = operand1 + operand2
                elif value == '-':
                    result = operand1 - operand2
                elif value == '*':
                    result = operand1 * operand2
                elif value == '/':
                    # Division by zero check
                    if operand2 == 0:
                        # Report position of the '/' operator
                        raise CalcError("Division by zero", position)
                    result = operand1 / operand2

                values.append(result)
            elif value == 'unary_minus':
                if len(values) < 1:
                    raise CalcError("Insufficient operands for unary minus", position)
                operand = values.pop()
                values.append(-operand)

        else:
            # Should not happen if shunting_yard is correct
            raise CalcError(f"Unknown token type: {op_type}", position)

    if len(values) != 1:
        raise CalcError("Malformed expression: too many operands left over", 0) # Use 0 or end position for general syntax error

    return values[0]

