import itertools

def escape_cell_text(text: any) -> str:
    """Converts input to string, handles None, escapes '|', and replaces newlines with <br>."""
    if text is None:
        return ""
    text = str(text)
    # Replace newlines first to avoid issues with escaped characters
    text = text.replace("\n", "<br>")
    text = text.replace("\r\n", "<br>")
    text = text.replace("|", "\\|")
    return text

def pad_cell(cell_text: str, width: int, alignment: str) -> str:
    """Pads the cell text according to the specified alignment and width."""
    if alignment == 'left':
        return cell_text.ljust(width)
    elif alignment == 'right':
        return cell_text.rjust(width)
    elif alignment == 'center':
        # Split padding: smaller half on the left
        padding_total = width - len(cell_text)
        left_pad = padding_total // 2
        right_pad = padding_total - left_pad
        return ' ' * left_pad + cell_text + ' ' * right_pad
    # Default to left if alignment is invalid or missing, though validation should catch this
    return cell_text.ljust(width)

def calculate_widths_and_texts(rows, headers, align):
    """Calculates the maximum required width for each column and prepares all escaped texts."""
    num_cols = len(headers)
    if num_cols == 0:
        raise ValueError("Headers must not be empty.")

    # Initialize widths with header content
    escaped_headers = [escape_cell_text(h) for h in headers]
    column_widths = [max(3, len(h)) for h in escaped_headers]

    # Process rows
    for i, row in enumerate(rows):
        if not isinstance(row, (list, tuple)) or len(row) != num_cols:
            raise ValueError(f"Row {i} must have exactly {num_cols} cells.")

        escaped_row = [escape_cell_text(cell) for cell in row]

        # Update widths
        for j in range(num_cols):
            column_widths[j] = max(column_widths[j], len(escaped_row[j]))

    return column_widths, escaped_headers, [escaped_row for escaped_row in rows]

def generate_separator_line(column_widths: list[int], align: list[str]) -> str:
    """Generates the Markdown separator line based on widths and alignment."""
    separator_parts = []
    for i, width in enumerate(column_widths):
        align_type = align[i]
        dashes = '-' * width

        if align_type == 'left':
            # First dash is ':'
            sep = ':' + dashes[1:]
        elif align_type == 'right':
            # Last dash is ':'
            sep = dashes[:-1] + ':'
        elif align_type == 'center':
            # Both first and last dashes are ':'
            sep = ':' + dashes[1:-1] + ':'
        else:
            raise ValueError(f"Unknown alignment type: {align_type}")
        separator_parts.append(sep)

    return "| " + " | ".join(separator_parts) + " |"

def format_table(rows, headers, align=None) -> str:
    """Renders a padded GitHub-flavoured Markdown table."""

    # 1. Input Validation and Initialization
    if not headers:
        raise ValueError("Headers must be a non-empty sequence.")
    if align is None:
        align = ['left'] * len(headers)
    elif not isinstance(align, (list, tuple)) or len(align) != len(headers):
        raise ValueError("Alignment sequence must match the number of columns.")
    else:
        # Validate alignment types
        valid_alignments = {'left', 'right', 'center'}
        for a in align:
            if a not in valid_alignments:
                raise ValueError(f"Unknown alignment entry: {a}. Must be one of {valid_alignments}")

    # 2. Calculate Widths and Escape Texts
    try:
        column_widths, escaped_headers, escaped_rows = calculate_widths_and_texts(rows, headers, align)
    except ValueError as e:
        # Re-raise validation errors from helper functions
        raise e

    # 3. Format Header Line
    header_cells = []
    for i, header in enumerate(escaped_headers):
        width = column_widths[i]
        alignment = align[i]
        header_cells.append(pad_cell(header, width, alignment))

    header_line = "| " + " | ".join(header_cells) + " |"

    # 4. Generate Separator Line
    separator_line = generate_separator_line(column_widths, align)

    # 5. Format Data Rows
    data_lines = []
    for escaped_row in escaped_rows:
        row_cells = []
        for i, cell in enumerate(escaped_row):
            width = column_widths[i]
            alignment = align[i]
            row_cells.append(pad_cell(cell, width, alignment))

        data_lines.append("| " + " | ".join(row_cells) + " |")

    # 6. Assemble Final String (No trailing newline)
    all_lines = [header_line, separator_line] + data_lines

    return '\n'.join(all_lines)

