                    return []

                else:
                    # Standard segment traversal
                    if isinstance(current_obj, dict) and segment in current_obj:
                        results.extend(traverse(current_obj[segment], seg_index + 1, current_path + [segment]))
                    elif isinstance(current_obj, list) and isinstance(segment, int) and 0 <= segment < len(current_obj):
                        results.extend(traverse(current_obj[segment], seg_index + 1, current_path + [segment]))
