            # Since we modified new_obj entirely, we will trust that the internal structures referenced by obj have been replaced by the path traversal logic.

            # A practical solution for in-place mutation of the root object: 
            # If the root object is a dict, we clear and update. If it's a list, we replace its contents.
            if isinstance(obj, dict) and isinstance(new_obj, dict):
                obj.clear()
                obj.update(new_obj)
            elif isinstance(obj, list) and isinstance(new_obj, list):
