def is_valid(grid: list[list[int]]) -> bool:
    """
    Checks if the current state of the puzzle adheres to Sudoku rules.

    Returns True if no digit 1–9 appears twice in any row, column or 3×3 box.
    Empty cells (0) never conflict.

    Raises:
        ValueError: If the grid does not have the required 9x9 shape or contains invalid values.
    """
    # Check shape and value validity first (leveraging helper logic)
    if not _validate_grid(grid):
        raise ValueError("Grid must be 9x9 with values between 0 and 9.")

    # Check rows
    for row in grid:
        seen = set()
        for val in row:
            if val != 0 and val in seen:
                return False
            seen.add(val)

    # Check columns
    for c in range(9):
        seen = set()
        for r in range(9):
            val = grid[r][c]
            if val != 0 and val in seen:
                return False
            seen.add(val)

    # Check 3x3 boxes
    for box_r_start in range(0, 9, 3):
        for box_c_start in range(0, 9, 3):
            seen = set()
            for r in range(box_r_start, box_r_start + 3):
                for c in range(box_c_start, box_c_start + 3):
                    val = grid[r][c]
                    if val != 0 and val in seen:
                        return False
                    seen.add(val)

    return True
