def solve(grid: list[list[int]]) -> list[list[int]] | None:
    """
    Finds a completed, valid Sudoku grid starting from the given state.

    Returns a new, solved grid, or None if no solution exists.
    The original grid is never modified.
    """
    # Create a deep copy of the grid to avoid modifying the original
    grid_copy = [row[:] for row in grid]

    # Initial validation check
    try:
        if not is_valid(grid):
            return None
    except ValueError:
        # If the initial grid is structurally invalid, we cannot solve it.
        return None

    def find_empty(g):
        """Finds the next empty cell (represented by 0). Returns (row, col) or None if full."""
        for r in range(9):
            for c in range(9):
                if g[r][c] == 0:
                    return r, c
        return None

    def is_safe(g, r, c, num):
        """Checks if 'num' can be placed at grid[r][c] based on Sudoku rules."""
        # Check row
        if num in g[r]:
            return False

        # Check column
        if num in [g[i][c] for i in range(9)]:
            return False

        # Check 3x3 box
        start_row = r - r % 3
        start_col = c - c % 3
        for i in range(3):
            for j in range(3):
                if g[start_row + i][start_col + j] == num:
                    return False

        return True

    def solve_util(g):
        """Recursive backtracking utility function."""
        find = find_empty(g)
        if not find:
            # Grid is full and valid
            return [row[:] for row in g] # Return a copy of the solved grid

        r, c = find

        for num in range(1, 10):
            if is_safe(g, r, c, num):
                g[r][c] = num

                # Recurse
                result = solve_util(g)
                if result:
                    return result

                # Backtrack: reset the cell
                g[r][c] = 0

        # If no number from 1-9 works for this cell, trigger backtracking
        return None

    return solve_util(grid_copy)

