from typing import List, Tuple, Dict, Optional, Set, Any
import copy

# Note: The candidate generation function must be defined before hint/difficulty.

def get_candidates(grid: List[List[int]], r: int, c: int, candidates_map: Dict[Tuple[int, int], Set[int]]) -> Set[int]:
    """
    Calculates all possible candidates (1-9) for the cell at (r, c) based on the grid state.
    This function relies on an external candidates_map which is built once per grid check.
    """
    if grid[r][c] != 0:
        return set()
    return candidates_map.get((r, c), set())


def calculate_candidates(grid: List[List[int]]) -> Dict[Tuple[int, int], Set[int]]:
    """
    Calculates and returns a map of all empty cells (r, c) to a set of their valid candidates.
    """
    candidates: Dict[Tuple[int, int], Set[int]] = {}

    def is_safe(r: int, c: int, num: int, current_grid: List[List[int]]) -> bool:
        # Check row
        if num in current_grid[r]:
            return False
        # Check column
        for i in range(9):
            if current_grid[i][c] == num:
                return False
        # Check 3x3 box
        start_row, start_col = 3 * (r // 3), 3 * (c // 3)
        for i in range(start_row, start_row + 3):
            for j in range(start_col, start_col + 3):
                if current_grid[i][j] == num:
                    return False
        return True

    for r in range(9):
        for c in range(9):
            if grid[r][c] == 0:
                possible_candidates: Set[int] = set()
                for num in range(1, 10):
                    if is_safe(r, c, num, grid):
                        possible_candidates.add(num)
                candidates[(r, c)] = possible_candidates

    return candidates


def hint(grid: List[List[int]]) -> Optional[Tuple[int, int, int, str]]:
    """
    Returns the next logical step as (row, col, digit, reason) based on Naked or Hidden Singles.
    """
    if not grid: raise ValueError("Grid cannot be empty.")
    if any(len(row) != 9 for row in grid): raise ValueError("Grid must be 9x9.")
    if any(not all(0 <= cell <= 9 for cell in row) for row in grid): raise ValueError("Grid values must be between 0 and 9.")

    candidates_map = calculate_candidates(grid)

    # 1. Naked Single Check (Row-major order)
    for r in range(9):
        for c in range(9):
            if grid[r][c] == 0:
                candidates = candidates_map.get((r, c))
                if candidates and len(candidates) == 1:
                    digit = candidates.pop()
                    return (r, c, digit, 'naked single')

    # 2. Hidden Single Check

    # Check Rows
    for r in range(9):
        row_candidates: Dict[int, List[Tuple[int, int]]] = {d: [] for d in range(1, 10)}
        for c in range(9):
            if grid[r][c] == 0:
                candidates = candidates_map.get((r, c))
                if candidates and grid[r][c] == 0:
                    for digit in candidates:
                        row_candidates[digit].append((r, c))

        for digit, positions in row_candidates.items():
            if len(positions) == 1:
                # Found a hidden single in this row
                return (positions[0][0], positions[0][1], digit, 'hidden single in row')

    # Check Columns
    for c in range(9):
        col_candidates: Dict[int, List[Tuple[int, int]]] = {d: [] for d in range(1, 10)}
        for r in range(9):
            if grid[r][c] == 0:
                candidates = candidates_map.get((r, c))
                if candidates and grid[r][c] == 0:
                    for digit in candidates:
                        col_candidates[digit].append((r, c))

        for digit, positions in col_candidates.items():
            if len(positions) == 1:
                # Found a hidden single in this column
                return (positions[0][0], positions[0][1], digit, 'hidden single in column')

    # Check Boxes
    for b in range(9):
        box_candidates: Dict[int, List[Tuple[int, int]]] = {d: [] for d in range(1, 10)}
        start_row, start_col = 3 * (b // 3), 3 * (b % 3)

        for r_offset in range(3):
            for c_offset in range(3):
                r, c = start_row + r_offset, start_col + c_offset
                if grid[r][c] == 0:
                    candidates = candidates_map.get((r, c))
                    if candidates and grid[r][c] == 0:
                        for digit in candidates:
                            box_candidates[digit].append((r, c))

        for digit, positions in box_candidates.items():
            if len(positions) == 1:
                # Found a hidden single in this box
                return (positions[0][0], positions[0][1], digit, 'hidden single in box')

    return None

def difficulty(grid: List[List[int]]) -> Optional[Dict[str, int]]:
    """
    Calculates the difficulty of a Sudoku puzzle by simulating the solving
    process using logical hints.
    """
    current_grid = copy.deepcopy(grid)
    naked_steps = 0
    hidden_steps = 0

    while True:
        # Check for completion
        is_complete = all(cell != 0 for row in current_grid for cell in row)

        if is_complete:
            return {"naked": naked_steps, "hidden": hidden_steps}

        # Find the next logical step
        hint_result = hint(current_grid)

        if hint_result is None:
            # No logical step found, puzzle stalls (needs guessing or has no solution)
            return None

        # Process the hint and update the grid
        row, col, digit, reason = hint_result
        current_grid[row][col] = digit

        # Count the step type
        if reason == 'naked single':
            naked_steps += 1
        elif 'hidden single' in reason:
            hidden_steps += 1

        # Safety break
        if naked_steps + hidden_steps > 200:
            return None

