import re
from dataclasses import dataclass
from typing import List, Dict, Any


def normalize_title(title: str) -> str:
    """Strips surrounding whitespace and returns the result. Raises ValueError if nothing is left."""
    normalized = title.strip()
    if not normalized:
        raise ValueError("Title cannot be empty or only whitespace.")
    return normalized

def normalize_tag(tag: str) -> str:
    """Strips surrounding whitespace and lowercases. The result must match [a-z0-9][a-z0-9_-]* in full, or ValueError is raised."""
    normalized = tag.strip().lower()
    if not normalized or not re.fullmatch(r'[a-z0-9][a-z0-9_-]*', normalized):
        raise ValueError(f"Invalid tag format: '{tag}'")
    return normalized

@dataclass
class Task:
    id: int
    title: str
    tags: List[str]
    done: bool = False

    def to_dict(self) -> Dict[str, Any]:
        """Returns a dictionary representation of the task with keys in a specific order."""
        return {"id": self.id, "title": self.title, "tags": self.tags, "done": self.done}

    @classmethod
    def from_dict(cls, d: Dict[str, Any]) -> "Task":
        """Builds a task from a dictionary, performing all necessary validations and normalizations."""
        try:
            task_id = d['id']
            title = d['title']
            tags = d['tags']
            done = d['done']
        except KeyError as e:
            raise ValueError(f"Missing key in task dictionary: {e}")

        if not isinstance(task_id, int) or task_id <= 0:
            raise ValueError("Task ID must be a positive integer.")
        if not isinstance(title, str):
            raise ValueError("Task title must be a string.")
        if not isinstance(tags, list) or not all(isinstance(t, str) for t in tags):
            raise ValueError("Task tags must be a list of strings.")
        if not isinstance(done, bool):
            raise ValueError("Task 'done' field must be a boolean.")

        # Normalization and Validation
        try:
            normalized_title = normalize_title(title)
        except ValueError as e:
            raise ValueError(f"Invalid title: {e}")

        try:
            # Normalize and validate each tag
            normalized_tags = [normalize_tag(t) for t in tags]
        except ValueError as e:
            raise ValueError(f"Invalid tag found: {e}")

        # Ensure tags are unique and sorted
        final_tags = sorted(list(set(normalized_tags)))

        return cls(id=task_id, title=normalized_title, tags=final_tags, done=done)


def normalize_tag(tag: str) -> str:
    """Strips surrounding whitespace and lowercases. The result must match [a-z0-9][a-z0-9_-]* in full, or ValueError is raised."""
    normalized = tag.strip().lower()
    if not re.fullmatch(r'[a-z0-9][a-z0-9_-]*', normalized):
        raise ValueError(f"Tag '{tag}' is invalid. Must match pattern [a-z0-9][a-z0-9_-]*. """ 
