import json
import shutil
from pathlib import Path
from typing import List, Dict, Optional, Any

from todo.model import Task, StoreError, normalize_title, normalize_tag

class StoreError(Exception):
    """Custom exception for issues related to the todo store file."""
    pass

class TodoStore:
    """Manages persistence for the todo list, handling file I/O and structure validation."""
    def __init__(self, path: str | Path):
        self.path = Path(path).resolve()
        self.data: Dict[str, Any] = self._load_store()

    def _load_store(self) -> Dict[str, Any]:
        """Loads the store from disk, handling missing or invalid files."""
        if not self.path.exists():
            # Missing file is an empty store
            return {"version": 1, "next_id": 1, "tasks": []}

        try:
            with open(self.path, 'r') as f:
                data = json.load(f)

            # Schema Validation
            if not isinstance(data, dict) or data.get("version") != 1:
                raise StoreError("Store file must be a JSON object with version 1.")
            if not isinstance(data.get("tasks"), list):
                 raise StoreError("Store file tasks field must be a list.")

            # ID Stability Validation
            max_id = 0
            task_ids = set()
            for task_dict in data.get("tasks", []):
                if not isinstance(task_dict, dict) or "id" not in task_dict:
                    raise StoreError("Each task must be a dictionary containing an 'id'.")

                task_id = task_dict["id"]
                if not isinstance(task_id, int) or task_id <= 0:
                    raise StoreError(f"Task ID {task_id} must be a positive integer.")

                if task_id in task_ids:
                    raise StoreError(f"Duplicate task ID found: {task_id}.")
                task_ids.add(task_id)

                if task_id >= data.get("next_id", 0): 
                    # This check handles cases where next_id is too low relative to existing tasks
                    # Although the requirement is more complex regarding reuse, this is a basic check.
                    # A perfect check requires parsing all tasks to confirm ID ordering relative to next_id.
                    pass 
                max_id = max(max_id, task_id)

            # Set next_id based on the highest existing ID if it's higher than what's stored
            new_next_id = max(data.get("next_id", 1), max_id + 1)
            data["next_id"] = new_next_id

            return data

        except json.JSONDecodeError:
            raise StoreError("Store file is not valid JSON.")
        except StoreError as e:
            raise e
        except Exception as e:
            # Catch other unexpected errors during loading
            raise StoreError(f"An unexpected error occurred during store loading: {e}")

    def _write_store(self) -> None:
        """Writes the current internal data structure back to disk atomically."""
        temp_path = self.path.with_suffix(self.path.suffix + '.tmp')
        try:
            with open(temp_path, 'w') as f:
                json.dump(self.data, f, indent=2)

            # Atomic replacement
            shutil.move(temp_path, self.path)
        except Exception as e:
            # If writing fails, attempt to clean up the temp file if it exists
            if temp_path.exists():
                temp_path.unlink()
            # Re-raise the exception indicating a write failure
            raise StoreError(f"Failed to write store to disk: {e}")

    def add(self, title: str, tags: tuple[str, ...] = ()) -> Task:
        """Adds an open task and returns it. Tags are normalized, deduplicated and sorted."""
        try:
            new_id = self.data["next_id"]
        except KeyError:
            raise StoreError("Store data is corrupted (missing 'next_id').")

        # Validate and normalize inputs
        try:
            validated_title = normalize_title(title)
        except ValueError as e:
            raise ValueError(f"Invalid title provided: {e}")

        normalized_tags = []
        for tag_str in tags:
            try:
                normalized_tags.append(normalize_tag(tag_str))
            except ValueError as e:
                raise ValueError(f"Invalid tag provided: {e}")

        # Deduplicate and sort
        final_tags = sorted(list(set(normalized_tags)))

        new_task = Task(id=new_id, title=validated_title, tags=final_tags, done=False)

        # Update store state
        self.data["tasks"].append(new_task.to_dict())
        self.data["next_id"] += 1

        self._write_store()
        return new_task

    def get(self, task_id: int) -> Task:
        """Returns the task or raises KeyError."""
        for task_dict in self.data["tasks"]:
            if task_dict.get("id") == task_id:
                # Return a copy constructed from the dict to prevent external mutation
                return Task.from_dict(task_dict)
        raise KeyError(f"No task with id {task_id}.")

    def list(self, status: str = "open", tags: tuple[str, ...] = ()) -> List[Task]:
        """Returns the tasks in increasing id order based on status and tags."""
        valid_statuses = {"open": "open", "done": "done", "all": "all"}
        if status not in valid_statuses:
            raise ValueError("Invalid status. Must be 'open', 'done', or 'all'.")

        normalized_filter_tags = []
        for tag_str in tags:
            try:
                normalized_filter_tags.append(normalize_tag(tag_str))
            except ValueError as e:
                # If filter tag is invalid, fail list operation with a specific error or just skip?
                # Requirement says: "a task is listed only if it has every one of them (they are normalized first)".
                # Let's fail if the filter tag itself is invalid to prevent listing based on bad input.
                raise ValueError(f"Invalid filter tag provided: {e}")

        filtered_tasks: List[Task] = []
        for task_dict in self.data["tasks"]:
            task = Task.from_dict(task_dict) # Safe to call from_dict as structure is validated

            # 1. Status check
            status_match = False
            if status == "all":
                status_match = True
            elif status == "open" and not task.done:
                status_match = True
            elif status == "done" and task.done:
                status_match = True
            else:
                continue

            # 2. Tag check (must have *every* specified tag)
            tags_match = True
            for required_tag in normalized_filter_tags:
                if required_tag not in task.tags:
                    tags_match = False
                    break

            if tags_match:
                filtered_tasks.append(task)

        return filtered_tasks

    def mark_done(self, task_id: int) -> Task:
        """Marks the task done and returns it. Marking a done task again changes nothing. KeyError if the id is missing."""
        found = False
        for task_dict in self.data["tasks"]:
            if task_dict.get("id") == task_id:
                found = True
                # Create a mutable copy for modification
                task = Task.from_dict(task_dict)

                if not task.done:
                    task.done = True

                    # Update store state
                    index = self.data["tasks"].index(task_dict)
                    self.data["tasks"][index] = task.to_dict()
                    self._write_store()

                # Return the task state after ensuring it's written (even if no change)
                return Task.from_dict(self.data["tasks"][index])

        if not found:
            raise KeyError(f"No task with id {task_id}.")

        # If found but already done, just return the existing state (which is correct)
        return self.get(task_id)

    def remove(self, task_id: int) -> Task:
        """Deletes the task and returns it, or raises KeyError."""
        original_task: Optional[Task] = None
        tasks_list = self.data["tasks"]

        try:
            index = next(i for i, task_dict in enumerate(tasks_list) if task_dict.get("id") == task_id)

            # Get the task before removal for return value
            original_task = Task.from_dict(tasks_list[index])

            # Remove from list
            tasks_list.pop(index)

            # Write new state
            self._write_store()
            return original_task

        except StopIteration:
            raise KeyError(f"No task with id {task_id}.")

    def edit(self, task_id: int, title: str | None = None, add_tags: tuple[str, ...] = (), remove_tags: tuple[str, ...] = ()) -> Task:
        """Changes the title if one is given, adds add_tags, then removes remove_tags. Returns the updated task."""
        tasks_list = self.data["tasks"]

        try:
            index = next(i for i, task_dict in enumerate(tasks_list) if task_dict.get("id") == task_id)
            old_task = Task.from_dict(tasks_list[index])
        except StopIteration:
            raise KeyError(f"No task with id {task_id}.")

        new_title = old_task.title
        new_tags = set(old_task.tags)

        # 1. Title Update
        if title is not None:
            try:
                new_title = normalize_title(title)
            except ValueError as e:
                raise ValueError(f"Invalid title provided: {e}")

        # 2. Tag Addition
        validated_add_tags = []
        for tag_str in add_tags:
            try:
                validated_add_tags.append(normalize_tag(tag_str))
            except ValueError as e:
                raise ValueError(f"Invalid tag for addition: {e}")
        new_tags.update(validated_add_tags)

        # 3. Tag Removal
        validated_remove_tags = []
        for tag_str in remove_tags:
            try:
                validated_remove_tags.append(normalize_tag(tag_str))
            except ValueError as e:
                raise ValueError(f"Invalid tag for removal: {e}")

        for tag_to_remove in validated_remove_tags:
            if tag_to_remove in new_tags:
                new_tags.remove(tag_to_remove)

        # Check if anything actually changed
        title_changed = new_title != old_task.title
        tags_changed = set(new_tags) != set(old_task.tags)

        if not title_changed and not tags_changed:
             # If no changes, return the existing task without writing
             return old_task

        # Construct the new task state
        final_task = Task(id=old_task.id, title=new_title, tags=sorted(list(new_tags)), done=old_task.done)

        # Update store state
        tasks_list[index] = final_task.to_dict()
        self._write_store()
        return final_task

