                        "tags": task.tags,
                        "done": task.done,
                        "priority": task.priority,
                        "due": task.due.isoformat() if task.due else None
                    }
                    migrated_tasks.append(task_v2_dict)
                    max_id = max(max_id, task.id)

                # Calculate new next_id based on migrated tasks
                new_next_id = max(data.get("next_id", 0) + 1, max_id + 1)

                return {
                    "version": self.STORE_VERSION,
                    "next_id": new_next_id,
                    "tasks": migrated_tasks
                }

            elif current_version == self.STORE_VERSION:
                # V2 file: proceed with standard validation
                # Schema Validation
                if not isinstance(data, dict) or data.get("version") != self.STORE_VERSION:
                    raise StoreError("Store file must be a JSON object with the correct version.")
                if not isinstance(data.get("tasks"), list):
                     raise StoreError("Store file tasks field must be a list.")

                # ID Stability Validation
                max_id = 0
                task_ids = set()
                for task_dict in data.get("tasks", []):
                    if not isinstance(task_dict, dict) or "id" not in task_dict:
                        raise StoreError("Each task must be a dictionary containing an 'id'.")

                    task_id = task_dict["id"]
                    if not isinstance(task_id, int) or task_id <= 0:
                        raise StoreError(f"Task ID {task_id} must be a positive integer.")

                    if task_id in task_ids:
                        raise StoreError(f"Duplicate task ID found: {task_id}.")
                    task_ids.add(task_id)

                    max_id = max(max_id, task_id)

                # Set next_id based on the highest existing ID if it's higher than what's stored
                new_next_id = max(data.get("next_id", 1), max_id + 1)
                data["next_id"] = new_next_id

                return data

            else:
                raise StoreError(f"Unsupported store version found: {current_version}. Expected {self.STORE_VERSION}.")

        except json.JSONDecodeError:
            raise StoreError("Store file is not valid JSON.")
        except StoreError as e:
            raise e
        except Exception as e:
            # Catch other unexpected errors during loading
            raise StoreError(f"An unexpected error occurred during store loading: {e}")

    def _write_store(self) -> None:
        """Writes the current internal data structure back to disk atomically, ensuring version 2."""
        self.data["version"] = self.STORE_VERSION
        temp_path = self.path.with_suffix(self.path.suffix + '.tmp')
        try:
            with open(temp_path, 'w') as f:
                json.dump(self.data, f, indent=2)

            # Atomic replacement
            shutil.move(temp_path, self.path)
        except Exception as e:
            # If writing fails, attempt to clean up the temp file if it exists
            if temp_path.exists():
                temp_path.unlink()
            # Re-raise the exception indicating a write failure
            raise StoreError(f"Failed to write store to disk: {e}")

    def add(self, title: str, tags: tuple[str, ...], priority: str = "normal", due: date | None = None) -> Task:
        """Adds an open task and returns it, supporting priority and due date."""
        try:
            new_id = self.data["next_id"]
        except KeyError:
            raise StoreError("Store data is corrupted (missing 'next_id').")

        # Validate and normalize inputs
        try:
            validated_title = normalize_title(title)
        except ValueError as e:
            raise ValueError(f"Invalid title provided: {e}")

        # Validate Priority
        try:
            validated_priority = normalize_priority(priority)
        except ValueError as e:
            raise ValueError(f"Invalid priority provided: {e}")

        # Validate Date
        validated_due = None
        if due is not None:
            try:
                # Assumes input `due` is already datetime.date object if passed from CLI layer
                if not isinstance(due, date):
                    raise TypeError
                validated_due = due
            except Exception:
                raise ValueError("Invalid due date format. Must be YYYY-MM-DD.")

        # Validate and normalize tags
        normalized_tags = []
        for tag_str in tags:
            try:
                normalized_tags.append(normalize_tag(tag_str))
            except ValueError as e:
                raise ValueError(f"Invalid tag provided: {e}")

        # Deduplicate and sort
        final_tags = sorted(list(set(normalized_tags)))

        # Create task using the Task constructor which now handles V2 fields
        new_task = Task(id=new_id, title=validated_title, tags=final_tags, done=False, priority=validated_priority, due=validated_due)

        # Update store state
        self.data["tasks"].append(new_task.to_dict())
        self.data["next_id"] += 1

        self._write_store()
        return new_task

    def get(self, task_id: int) -> Task:
        """Returns the task or raises KeyError."""
        for task_dict in self.data["tasks"]:
            if task_dict.get("id") == task_id:
                # Return a copy constructed from the dict to prevent external mutation
                return Task.from_dict(task_dict)
        raise KeyError(f"No task with id {task_id}.")

    def list(self, status: str = "open", tags: tuple[str, ...] = (), overdue: bool = False, today: date | None = None, sort: str = "id") -> List[Task]:
        """Returns the tasks, filtered and sorted according to complex rules."""
        valid_statuses = {"open": "open", "done": "done", "all": "all"}
        if status not in valid_statuses:
            raise ValueError("Invalid status. Must be 'open', 'done', or 'all'.")

        # Validate sorting parameter
        valid_sorts = {"id": 1, "priority": 2, "due": 3}
        if sort not in valid_sorts:
             raise ValueError("Invalid sort method. Must be 'id', 'priority', or 'due'.")

        # Validate overdue and today relationship
        if overdue and today is None:
            raise ValueError("The --overdue flag requires the --today option to be specified.")

        normalized_filter_tags = []
        for tag_str in tags:
            try:
                normalized_filter_tags.append(normalize_tag(tag_str))
            except ValueError as e:
                raise ValueError(f"Invalid filter tag provided: {e}")

        tasks_to_process: List[Task] = []
        for task_dict in self.data["tasks"]:
            try:
                # Task.from_dict must now handle V2 structure seamlessly
                task = Task.from_dict(task_dict)
                tasks_to_process.append(task)
            except Exception as e:
                # Should not happen if store migration is perfect, but catch deserialization failure
                print(f"Warning: Could not deserialize task: {e}")
                continue

        # 1. Filtering (Status and Tags)
        filtered_tasks: List[Task] = []
        for task in tasks_to_process:

            # Status check
            if status == "all":
                status_match = True
            elif status == "open" and not task.done:
                status_match = True
            elif status == "done" and task.done:
                status_match = True
            else:
                continue

            # Tag check (must have *every* specified tag)
            tags_match = all(required_tag in task.tags for required_tag in normalized_filter_tags)

            if tags_match:
                # 2. Overdue check
                is_overdue = False
                if overdue and task.done is False and today is not None:
                    # Strictly before today
                    if task.due is not None and task.due < today:
                        is_overdue = True

                if is_overdue:
                    filtered_tasks.append(task)
                elif not overdue: # Only proceed if overdue filtering wasn't applied
                    filtered_tasks.append(task)

        # 3. Sorting
        def sort_key(task: Task) -> Tuple[int, Any]:
            # Sort key must be stable: (Primary_Sort_Value, Secondary_Sort_Value)
            # Secondary sort is always increasing ID for tie-breaking

            if sort == "id":
                return (0, task.id)

            elif sort == "priority":
                # High (0), Normal (1), Low (2)
                p_map = {"high": 0, "normal": 1, "low": 2}
                priority_value = p_map.get(task.priority, 1)
                return (priority_value, task.id)

            elif sort == "due":
                # Earliest due date first. Tasks without due date go last.
                if task.due is None:
                    # Assign a very large date object (e.g., year 9999) to push them to the end
                    return (1, 9999)
                else:
                    # Assign a smaller value (0) for tasks with due dates. Use date object for proper comparison.
                    return (0, task.due)

        # Apply the sorting
        return sorted(filtered_tasks, key=sort_key)

    def edit(self, task_id: int, title: str | None = None, add_tags: tuple[str, ...] = (), remove_tags: tuple[str, ...] = (), priority: str | None = None, due: date | None = None, clear_due: bool = False) -> Task:
        """Changes task fields. Supports new priority/due fields."""
        tasks_list = self.data["tasks"]

        try:
            index = next(i for i, task_dict in enumerate(tasks_list) if task_dict.get("id") == task_id)
            old_task = Task.from_dict(tasks_list[index])
        except StopIteration:
            raise KeyError(f"No task with id {task_id}.")

        new_title = old_task.title
        new_tags = set(old_task.tags)
        new_priority = old_task.priority
        new_due = old_task.due

        # 1. Title Update
        if title is not None:
            try:
                new_title = normalize_title(title)
            except ValueError as e:
                raise ValueError(f"Invalid title provided: {e}")

        # 2. Tag Addition
        validated_add_tags = []
        for tag_str in add_tags:
            try:
                validated_add_tags.append(normalize_tag(tag_str))
            except ValueError as e:
                raise ValueError(f"Invalid tag for addition: {e}")
        new_tags.update(validated_add_tags)

        # 3. Tag Removal
        validated_remove_tags = []
        for tag_str in remove_tags:
            try:
                validated_remove_tags.append(normalize_tag(tag_str))
            except ValueError as e:
                raise ValueError(f"Invalid tag for removal: {e}")

        for tag_to_remove in validated_remove_tags:
            if tag_to_remove in new_tags:
                new_tags.remove(tag_to_remove)

        # 4. Priority Update
        if priority is not None:
            try:
                new_priority = normalize_priority(priority)
            except ValueError as e:
                raise ValueError(f"Invalid priority provided: {e}")

        # 5. Due Date Update
        if clear_due:
            new_due = None
        elif due is not None:
            try:
                new_due = due # Assume input `due` is already datetime.date object
            except Exception:
                raise ValueError("Invalid due date format. Must be YYYY-MM-DD.")

        # Check for conflict between due and clear_due
        if due is not None and clear_due:
             raise ValueError("Cannot specify a due date while also setting clear_due=True.")

        # Check if anything actually changed
        title_changed = new_title != old_task.title
        tags_changed = set(new_tags) != set(old_task.tags)
        priority_changed = new_priority != old_task.priority
        due_changed = new_due != old_task.due

        if not title_changed and not tags_changed and not priority_changed and not due_changed:
             # If no changes, return the existing task without writing
             return old_task

        # Construct the new task state using Task constructor which handles V2 fields
        final_task = Task(id=old_task.id, title=new_title, tags=sorted(list(new_tags)), done=old_task.done, priority=new_priority, due=new_due)

        # Update store state
        tasks_list[index] = final_task.to_dict()
        self._write_store()
        return final_task

    def remove(self, task_id: int) -> Task:
        """Deletes the task and returns it, or raises KeyError."""
        original_task: Optional[Task] = None
        tasks_list = self.data["tasks"]

        try:
            index = next(i for i, task_dict in enumerate(tasks_list) if task_dict.get("id") == task_id)

            # Get the task before removal for return value
            original_task = Task.from_dict(tasks_list[index])

            # Remove from list
            tasks_list.pop(index)

            # Write new state
            self._write_store()
            return original_task

        except StopIteration:
            raise KeyError(f"No task with id {task_id}.")

