import re
from dataclasses import dataclass
from typing import List, Dict, Any, Optional
from datetime import date as date_type


def normalize_title(title: str) -> str:
    """Strips surrounding whitespace and returns the result. Raises ValueError if nothing is left."""
    normalized = title.strip()
    if not normalized:
        raise ValueError("Title cannot be empty or only whitespace.")
    return normalized


def normalize_priority(p: str) -> str:
    """Normalizes a priority string to 'high', 'normal', or 'low'."""
    p = p.strip().lower()
    if p not in ("high", "normal", "low"):
        raise ValueError(f"Invalid priority '{p}'. Must be 'high', 'normal', or 'low'.")
    return p


def parse_date(s: str) -> date_type:
    """Parses a date string in 'YYYY-MM-DD' format."""
    try:
        return date_type.fromisoformat(s)
    except ValueError:
        raise ValueError(f"Date '{s}' is not in the required YYYY-MM-DD format or is an invalid calendar date.")

@dataclass
class Task:
    id: int
    title: str
    tags: tuple[str, ...] = tuple()
    done: bool = False
    priority: str = "normal"
    due: Optional[date_type] = None

    def normalize_tag(self, tag: str) -> str:
        """Strips surrounding whitespace and validates a tag."""
        normalized = tag.strip().lower()
        if not re.fullmatch(r'[a-z0-9][a-z0-9_-]*', normalized):
            raise ValueError(f"Tag '{tag}' is invalid. Must match pattern [a-z0-9][a-z0-9_-]*.") 
        return normalized

    def to_dict(self) -> Dict[str, Any]:
        """Returns a dictionary representation of the task, including priority and due date in string format."""
        due_str = self.due.isoformat() if self.due else None
        return {
            "id": self.id,
            "title": self.title,
            "tags": list(self.tags),
            "done": self.done,
            "priority": self.priority,
            "due": due_str
        }

    @classmethod
    def from_dict(cls, d: Dict[str, Any]) -> 'Task':
        """Creates a Task instance from a dictionary, validating new fields."""
        # Handle older versions that might lack priority/due
        priority = d.get('priority', 'normal')
        due_str = d.get('due')

        try:
            validated_priority = normalize_priority(priority)
        except ValueError as e:
            raise ValueError(f"Invalid priority in data: {e}")

        due_date = None
        if due_str is not None:
            try:
                due_date = date_type.fromisoformat(due_str)
            except ValueError:
                raise ValueError(f"Invalid due date format in data: '{due_str}'. Must be YYYY-MM-DD.")

        return cls(
            id=d['id'],
            title=d['title'],
            tags=tuple(d.get('tags', [])),
            done=d.get('done', False),
            priority=validated_priority,
            due=due_date
        )

import json
import shutil
from pathlib import Path
from typing import List, Dict, Optional, Any, Tuple
from datetime import date

from todo.model import Task, StoreError, normalize_title, normalize_tag, normalize_priority, parse_date

# --- StoreError Definition (kept for completeness, assumed present) ---
class StoreError(Exception):
    """Custom exception for issues related to the todo store file."""
    pass

# --- Store Class ---
class TodoStore:
    """Manages persistence for the todo list, handling file I/O and structure validation."""
    # Version indicator for the store format
    STORE_VERSION = 2

    def __init__(self, path: str | Path):
        self.path = Path(path).resolve()
        self.data: Dict[str, Any] = self._load_store()

    def _load_store(self) -> Dict[str, Any]:
        """Loads the store from disk, handling missing or invalid files and migrating V1 to V2."""
        if not self.path.exists():
            # Missing file is an empty store, starting at version 2
            return {"version": self.STORE_VERSION, "next_id": 1, "tasks": []}

        try:
            with open(self.path, 'r') as f:
                data = json.load(f)

            # --- Version Handling ---
            current_version = data.get("version", 1)

            if current_version == 1:
                print("Upgrading store from version 1 to version 2...")
                # Migration step for V1 to V2
                tasks_v1 = data.get("tasks", [])
                migrated_tasks = []
                max_id = 0

                for task_dict in tasks_v1:
                    # V1 tasks lack priority and due
                    # We need to construct a minimal task that can be serialized to V2 format
                    task_dict["priority"] = "normal"
                    task_dict["due"] = None
                    task = Task.from_dict(task_dict)

                    # Ensure V2 structure compliance for storage
                    task_v2_dict = {
                        "id": task.id,
                        "title": task.title,
                        "tags": task.tags,
                        "done": task.done,
                        "priority": task.priority,
                        "due": task.due.isoformat() if task.due else None
                    }
                    migrated_tasks.append(task_v2_dict)
                    max_id = max(max_id, task.id)

                # Calculate new next_id based on migrated tasks
                new_next_id = max(data.get("next_id", 0) + 1, max_id + 1)

                return {
                    "version": self.STORE_VERSION,
                    "next_id": new_next_id,
                    "tasks": migrated_tasks
                }

            elif current_version == self.STORE_VERSION:
                # V2 file: proceed with standard validation
                # Schema Validation
                if not isinstance(data, dict) or data.get("version") != self.STORE_VERSION:
                    raise StoreError("Store file must be a JSON object with the correct version.")
                if not isinstance(data.get("tasks"), list):
                     raise StoreError("Store file tasks field must be a list.")

                # ID Stability Validation
                max_id = 0
                task_ids = set()
                for task_dict in data.get("tasks", []):
                    if not isinstance(task_dict, dict) or "id" not in task_dict:
                        raise StoreError("Each task must be a dictionary containing an 'id'.")

                    task_id = task_dict["id"]
                    if not isinstance(task_id, int) or task_id <= 0:
                        raise StoreError(f"Task ID {task_id} must be a positive integer.")

                    if task_id in task_ids:
                        raise StoreError(f"Duplicate task ID found: {task_id}.")
                    task_ids.add(task_id)

                    max_id = max(max_id, task_id)

                # Set next_id based on the highest existing ID if it's higher than what's stored
                new_next_id = max(data.get("next_id", 1), max_id + 1)
                data["next_id"] = new_next_id

                return data

            else:
                raise StoreError(f"Unsupported store version found: {current_version}. Expected {self.STORE_VERSION}.")

        except json.JSONDecodeError:
            raise StoreError("Store file is not valid JSON.")
        except StoreError as e:
            raise e
        except Exception as e:
            # Catch other unexpected errors during loading
            raise StoreError(f"An unexpected error occurred during store loading: {e}")

    def _write_store(self) -> None:
        """Writes the current internal data structure back to disk atomically, ensuring version 2."""
        self.data["version"] = self.STORE_VERSION
        temp_path = self.path.with_suffix(self.path.suffix + '.tmp')
        try:
            with open(temp_path, 'w') as f:
                json.dump(self.data, f, indent=2)

            # Atomic replacement
            shutil.move(temp_path, self.path)
        except Exception as e:
            # If writing fails, attempt to clean up the temp file if it exists
            if temp_path.exists():
                temp_path.unlink()
            # Re-raise the exception indicating a write failure
            raise StoreError(f"Failed to write store to disk: {e}")

