        except TemplateRenderError as e:
            raise TemplateRenderError(f"For loop expression evaluation failed: {e.message}", e.lineno)

        # 2. Handle loop iteration
        if iterable is None:
            # Looping over None gives no items
            return self._render_template_body(for_stmt.else_body, context, loop_state)

        output = []

