        current_loop_state = {
            'index': 0, 'index0': 0, 'first': True, 'last': False, 'length': len(iterable)
        }

        if isinstance(iterable, collections.abc.Mapping):
            # Mapping yields keys
            items_to_iterate = list(iterable.keys())
        elif isinstance(iterable, (list, tuple)):
