            raise TemplateRenderError(f"Cannot iterate over non-iterable type: {type(iterable).__name__}", for_stmt.lineno)

        # Render body for each item
        for i, item in enumerate(items_to_iterate):
            # Update loop state for this iteration
            current_loop_state['index'] = i + 1
            current_loop_state['index0'] = i
            current_loop_state['first'] = (i == 0)
            current_loop_state['last'] = (i == len(iterable) - 1)

            # Create a temporary context that includes the loop variable
            iteration_context = context.copy()
            iteration_context[for_stmt.name] = item

            # Render the body
            body_result = self._render_template_body(for_stmt.body, iteration_context, current_loop_state)
            output.append(body_result)

        # 3. Render else body if no iterations occurred (This logic is tricky: 'else' is rendered if the iterable was empty)
        if not items_to_iterate:
            output.append(self._render_template_body(for_stmt.else_body, context, loop_state))

        return "".join(output)

    def _render_if_statement(self, if_stmt: Node.IfStatement, context: Dict[str, Any], loop_state: Dict[str, Any]) -> str:
        # 1. Evaluate the condition of the first branch (COND)
        try:
            condition = self._evaluate_expression(if_stmt.condition, context, loop_state)
        except TemplateRenderError as e:
            raise TemplateRenderError(f"If condition evaluation failed: {e.message}", if_stmt.lineno)

        # 2. Execute branches based on evaluation
        if condition is True:
            return self._render_template_body(if_stmt.body, context, loop_state)
        elif condition is False:
            # Check subsequent elifs
            for elif_stmt in if_stmt.elifs:
                try:
                    elif_condition = self._evaluate_expression(elif_stmt.condition, context, loop_state)
                    if elif_condition is True:
                        return self._render_template_body(elif_stmt.body, context, loop_state)
                except TemplateRenderError as e:
                    raise TemplateRenderError(f"Elif condition evaluation failed: {e.message}", elif_stmt.lineno)

            # Check else block
            if if_stmt.else_body:
                return self._render_template_body(if_stmt.else_body, context, loop_state)
            return "" # No matching branch and no else
        else:
            # Condition was not a strict boolean (e.g., None, 0, empty list). Test Python truthiness.
            # The spec implies 'a bare value expression is tested with Python truthiness.'
            # If we reached here and the condition wasn't strictly True/False, we treat it as False for the initial branch.
            # Then we proceed to elifs/else.
            for elif_stmt in if_stmt.elifs:
                try:
                    elif_condition = self._evaluate_expression(elif_stmt.condition, context, loop_state)
                    if elif_condition:
                        return self._render_template_body(elif_stmt.body, context, loop_state)
                except TemplateRenderError as e:
                    raise TemplateRenderError(f"Elif condition evaluation failed: {e.message}", elif_stmt.lineno)

            if if_stmt.else_body:
                return self._render_template_body(if_stmt.else_body, context, loop_state)
            return "" 

    # --- Body Rendering Helpers ---

    def _render_template_body(self, body: Union[Node.Body, str], context: Dict[str, Any], loop_state: Dict[str, Any]) -> str:
        if isinstance(body, str):
            return body
        if isinstance(body, Node.Body):
            return self._render_nodes(body.nodes, context, loop_state)
        return ""

# Helper function for external usage (though Template class is preferred)
def render(source: str, context: Optional[Dict[str, Any]] = None, **kwargs) -> str:
    """Convenience function to render a source string directly."""
    template = Template(source)
    return template.render(context, **kwargs)

