                except TemplateRenderError as e:
                    raise TemplateRenderError(f"Elif condition evaluation failed: {e.message}", elif_stmt.lineno)

            # Check else block
            if if_stmt.else_body:
                return self._render_template_body(if_stmt.else_body, context, loop_state)
            return "" # No matching branch and no else
        else:
            # Condition was not a strict boolean (e.g., None, 0, empty list). Test Python truthiness.
