            if if_stmt.else_body:
                return self._render_template_body(if_stmt.else_body, context, loop_state)
            return "" 

    # --- Body Rendering Helpers ---

    def _render_template_body(self, body: Union[Node.Body, str], context: Dict[str, Any], loop_state: Dict[str, Any]) -> str:
        if isinstance(body, str):
            return body
        if isinstance(body, Node.Body):
            return self._render_nodes(body.nodes, context, loop_state)
        return ""

