from dataclasses import dataclass, field
from typing import List, Tuple, Optional, Callable, Any, Union

# --- Exceptions ---

class MachineError(Exception):
    """Base exception for FSM errors."""
    pass

class InvalidTransition(MachineError):
    """Raised when no transition matches the event in the current state."""
    def __init__(self, state: str, event: str):
        super().__init__(f"No transition found for event '{event}' in state '{state}'.")
        self.state = state
        self.event = event

class GuardRejected(MachineError):
    """Raised when all transitions for an event are rejected by guards."""
    def __init__(self, state: str, event: str):
        super().__init__(f"All transitions for event '{event}' in state '{state}' were rejected by guards.")
        self.state = state
        self.event = event

