        """Handles product selection logic."""
        # Check order: State (handled by FSM), Unknown code, SoldOut, InsufficientCredit
        if code not in self._products:
            raise KeyError(f"Product code '{code}' not found.")

        price, stock = self._products[code]

        if stock <= 0:
            raise SoldOut(f"Product {code} is sold out.")

        if self._credit < price:
            raise InsufficientCredit(f"Insufficient credit. Price is {price}, have {self._credit}.")

        # Transaction successful
        self._credit -= price
        self._products[code] = (price, stock - 1)
