        # Accepted coins for validation
        self._accepted_coins = {5, 10, 25, 100}

    # --- Internal FSM Hook Handlers (Called via Transition actions) ---

    def _handle_insert(self, coin: int) -> None:
        """Handles coin insertion logic."""
        if coin not in self._accepted_coins:
            raise ValueError(f"Coin {coin} is not accepted.")

        self._credit += coin
        # State change is handled by FSM transition (idle -> credit)

    def _handle_select(self, code: str) -> None:
        """Handles product selection logic."""
        # Check order: State (handled by FSM), Unknown code, SoldOut, InsufficientCredit
        if code not in self._products:
            raise KeyError(f"Product code '{code}' not found.")

        price, stock = self._products[code]

        if stock <= 0:
            raise SoldOut(f"Product {code} is sold out.")

        if self._credit < price:
            raise InsufficientCredit(f"Insufficient credit. Price is {price}, have {self._credit}.")

        # Transaction successful
        self._credit -= price
        self._products[code] = (price, stock - 1)
        self._sales[code] = self._sales.get(code, 0) + 1
        self._revenue += price

        # State change is handled by FSM transition (credit -> idle)

    def _handle_cancel(self) -> None:
        """Handles cancellation and refund logic."""
        if self._credit == 0:
            return # Nothing to refund

        # Greedy refund (100, 25, 10, 5)
        refund_coins = []
        remaining_credit = self._credit
        coins_to_use = [100, 25, 10, 5]

        for coin_value in coins_to_use:
            while remaining_credit >= coin_value:
                refund_coins.append(coin_value)
                remaining_credit -= coin_value

        self._credit = 0
        # State change is handled by FSM transition (credit -> idle)

    def _handle_restock(self, code: str, qty: int, price: Optional[int]) -> None:
        """Handles restock logic in maintenance mode."""
        if qty < 1:
            raise ValueError("Restock quantity must be at least 1.")

        if code not in self._products:
            if price is None:
                raise KeyError(f"Price must be provided for new product code '{code}'.")
            # New product
            self._products[code] = (price, qty)
        else:
            # Existing product: update stock and potentially price
            old_price, old_stock = self._products[code]
            self._products[code] = (price if price is not None else old_price, old_stock + qty)

        # State remains 'maintenance' (internal transition)

    # --- Public Methods ---

    def insert(self, coin: int) -> int:
        """Inserts a coin and updates credit."""
        if self.machine.state not in ['idle', 'credit']:
            raise fsm.InvalidTransition(self.machine.state, 'insert')

        try:
            self.machine.fire('insert', coin=coin)
        except ValueError as e:
            # Coin not accepted, state/credit unchanged
            raise e

        return self._credit

    def select(self, code: str) -> List[int]:
        """Selects a product, handles transaction, returns change as coins."""
        if self.machine.state != 'credit':
            raise fsm.InvalidTransition(self.machine.state, 'select')

        try:
            # Attempt the transaction. The action handler (_handle_select) raises specific exceptions.
            self.machine.fire('select', code=code)
        except KeyError:
            raise
        except SoldOut:
            raise
        except InsufficientCredit:
            raise
        finally:
            # If the FSM transition succeeded, state is now 'idle', credit is updated.
            pass

        # Calculate and return change as greedy coins
        return self._calculate_change(self._credit)

    def cancel(self) -> List[int]:
        """Refunds the current credit."""
        if self.machine.state != 'credit':
            raise fsm.InvalidTransition(self.machine.state, 'cancel')

        try:
            self.machine.fire('cancel')
        except Exception as e:
            raise e

        return self._calculate_change(self._credit)

    def service(self) -> None:
        """Moves the machine to maintenance mode."""
        if self.machine.state != 'idle':
            raise fsm.InvalidTransition(self.machine.state, 'service')

        self.machine.fire('service')

    def restock(self, code: str, qty: int, price: Optional[int] = None) -> None:
        """Restocks inventory or sets price for a new product."""
        if self.machine.state != 'maintenance':
            raise fsm.InvalidTransition(self.machine.state, 'restock')

        try:
            # Use internal transition that doesn't change state
            self.machine.fire('restock', code=code, qty=qty, price=price)
        except Exception as e:
            raise e

    def resume(self) -> None:
        """Returns the machine from maintenance to idle."""
        if self.machine.state != 'maintenance':
            raise fsm.InvalidTransition(self.machine.state, 'resume')

        self.machine.fire('resume')

    # --- Read-Only Views ---

    @property
    def state(self) -> str:
        """The current state of the machine."""
        return self.machine.state

    @property
    def credit(self) -> int:
        """The current inserted credit amount in cents."""
        return self._credit

    def stock(self, code: str) -> int:
        """Returns the current stock level for a product code."""
        try:
            return self._products[code][1]
        except KeyError:
            raise KeyError(f"Product code '{code}' unknown.")

    def price(self, code: str) -> int:
        """Returns the price for a product code in cents."""
        try:
            return self._products[code][0]
        except KeyError:
            raise KeyError(f"Product code '{code}' unknown.")

    def sales(self) -> Dict[str, int]:
        """Returns a dictionary of units sold per code."""
        return self._sales

    @property
    def revenue(self) -> int:
        """Total revenue generated in cents."""
        return self._revenue

    # --- Utility ---

    def _calculate_change(self, amount: int) -> List[int]:
        """Calculates change from a given amount greedily."""
        coins = [100, 25, 10, 5]
        change_coins = []
        remaining = amount
        for coin_value in coins:
            while remaining >= coin_value:
                change_coins.append(coin_value)
                remaining -= coin_value
        return change_coins


class VendingError(Exception):
    """Base exception for Vending Machine errors."""
    pass

class SoldOut(VendingError):
    """Raised when a product is out of stock."""
    pass

class InsufficientCredit(VendingError):
    """Raised when the credit is less than the product price."""
    pass

from enum import Enum
from dataclasses import dataclass

class AccountType(str, Enum):
    """Defines the type of an account.
    """
    ASSET = "asset"
    LIABILITY = "liability"
    EQUITY = "equity"
    INCOME = "income"
    EXPENSE = "expense"

@dataclass(frozen=True)
class Account:
    """Represents a single account in the Chart of Accounts.
    """
    code: str
    name: str
    type: AccountType
    parent: str | None


    def _validate_account(self, code: str, name: str, type_val: str, parent: Optional[str]) -> Account:
        type_enum = None
        try:
            # Try to convert string type to Enum member
            type_enum = AccountType(type_val.lower())
        except ValueError:
            # If it fails, assume it's already the enum member object
            if isinstance(type_val, AccountType):
                type_enum = type_val
            else:
                raise ValueError(f"Unknown account type: {type_val}")

        if not code.isdigit() or not code:
            raise ValueError("Account code must be a non-empty string of digits.")

        if code in self._accounts:
            raise ValueError(f"Account code {code} already exists.")

        if parent and parent not in self._accounts:
            raise ValueError(f"Parent account code {parent} does not exist.")

        if parent and self._accounts[parent].type != type_enum:
            raise ValueError("A parent and child account must have the same type.")

        return Account(code=code, name=name, type=type_enum, parent=parent)

    def add(self, code: str, name: str, type_val: AccountType | str, parent: Optional[str] = None) -> Account:
        # Ensure type_val is consistent (AccountType or its string representation)
        if isinstance(type_val, str):
            type_val = AccountType(type_val.lower())

        # Use the private validation method
        new_account = self._validate_account(code, name, type_val, parent)
        self._accounts[code] = new_account
        return new_account

    def get(self, code: str) -> Account:
        account = self._accounts.get(code)
        if account is None:
            raise KeyError(f"Account with code {code} not found.")
        return account

    def children(self, code: str) -> list[Account]:
        if code not in self._accounts:
            raise KeyError(f"Account with code {code} not found.")

        children_list = []
        for account in self._accounts.values():
            if account.parent == code:
                children_list.append(account)

        # Sorted by code
        return sorted(children_list, key=lambda a: a.code)

    def roots(self) -> list[Account]:
        return sorted([acc for acc in self._accounts.values() if acc.parent is None], key=lambda a: a.code)

    def is_leaf(self, code: str) -> bool:
        if code not in self._accounts:
            raise KeyError(f"Account with code {code} not found.")

        # Check if any other account has this code as parent
        for account in self._accounts.values():
            if account.parent == code:
                return False
        return True

    def walk(self) -> list[tuple[Account, int]]:
        # Depth First Search implementation for walk()
        accounts_by_code = sorted(self._accounts.values(), key=lambda a: a.code)
        result = []

        def dfs(account: Account, depth: int):
            # Add current account
            result.append((account, depth))

            # Find and recurse on children, sorted by code
            children_of_current = sorted(
                (a for a in self._accounts.values() if a.parent == account.code), 
                key=lambda a: a.code
            )

            for child in children_of_current:
                dfs(child, depth + 1)

        # Start DFS from all roots, ordered by code
        roots = self.roots()
        for root in roots:
            dfs(root, 0)

        return result

from dataclasses import dataclass
from typing import List
from library.fines import POLICY, KeyError

@dataclass(frozen=True)
class Book:
    isbn: str
    title: str
    author: str
    copies: int

@dataclass(frozen=True)
class Member:
    member_id: str
    name: str
    kind: str

class Catalog:
    """Manages the library's book inventory and member registry."""
    def __init__(self):
        self._books: dict[str, Book] = {}
        self._members: dict[str, Member] = {}

    def add_book(self, isbn: str, title: str, author: str, copies: int = 1) -> Book:
        if isbn in self._books:
            raise ValueError(f"Book with ISBN {isbn} already exists.")
        if copies < 1:
            raise ValueError("Copies must be at least 1.")

        new_book = Book(isbn=isbn, title=title, author=author, copies=copies)
        self._books[isbn] = new_book
        return new_book

    def add_copies(self, isbn: str, n: int) -> int:
        if isbn not in self._books:
            raise KeyError(f"Book with ISBN {isbn} not found in catalog.")
        if n < 1:
            raise ValueError("Number of copies to add must be at least 1.")

        current_copies = self._books[isbn].copies
        new_copies = current_copies + n

        # Update the book object in place (since Book is frozen, we replace it)
        updated_book = self._books[isbn].replace(copies=new_copies)
        self._books[isbn] = updated_book
        return new_copies

    def add_member(self, member_id: str, name: str, kind: str = 'standard') -> Member:
        if member_id in self._members:
            raise ValueError(f"Member with ID {member_id} already exists.")
        if kind not in POLICY:
            raise ValueError(f"Member kind '{kind}' is not defined in policy.")

        new_member = Member(member_id=member_id, name=name, kind=kind)
        self._members[member_id] = new_member
        return new_member

    def book(self, isbn: str) -> Book:
        if isbn not in self._books:
            raise KeyError(f"Book with ISBN {isbn} not found.")
        return self._books[isbn]

    def member(self, member_id: str) -> Member:
        if member_id not in self._members:
            raise KeyError(f"Member with ID {member_id} not found.")
        return self._members[member_id]

    def search(self, text: str) -> List[Book]:
        text_lower = text.lower()
        results: List[Book] = []

        for book_obj in self._books.values():
            if text_lower in book_obj.title.lower() or text_lower in book_obj.author.lower():
                results.append(book_obj)

        # Sort by title, then by ISBN
        results.sort(key=lambda b: (b.title, b.isbn))
        return results

