# --- Headers Class ---

class Headers:
    def __init__(self, pairs: Tuple[Tuple[str, str], ...] = ()): # type: ignore
        # Stores pairs as [(name1, value1), (name2, value2), ...]
        self._pairs: List[Tuple[str, str]] = list(pairs)

    def add(self, name: str, value: str):
        # Appends a field
        self._pairs.append((name, value))

    def set(self, name: str, value: str):
        # Replaces every field with that name by a single one (at the position of the first, or at the end if there was none).
        lower_name = name.lower()
        found_index = -1

        # Find the first occurrence
        for i, (n, _) in enumerate(self._pairs):
            if n.lower() == lower_name:
                found_index = i
                break

        if found_index != -1:
            # Replace the existing entry
            self._pairs[found_index] = (name, value)
        else:
            # Add at the end
            self._pairs.append((name, value))

    def get(self, name: str, default: Any = None) -> Any:
        # Returns the first value (case-insensitive)
        lower_name = name.lower()
        for n, value in self._pairs:
            if n.lower() == lower_name:
                return value
        return default

    def __getitem__(self, name: str) -> str:
        # Raises KeyError if not found
        value = self.get(name)
        if value is None and self.get(name, object()) is None: # Check if default was returned
            raise KeyError(name)
        return value

    def get_all(self, name: str) -> List[str]:
        # Returns every value in order
        lower_name = name.lower()
        return [value for n, value in self._pairs if n.lower() == lower_name]

    def __contains__(self, name: str) -> bool:
        # Check for existence
        return self.get(name) is not None

    def __len__(self) -> int:
        # Number of unique fields (based on first occurrence)
        unique_names = set()
        count = 0
        for name, _ in self._pairs:
            if name.lower() not in unique_names:
                unique_names.add(name.lower())
                count += 1
        return count

    def items(self) -> List[Tuple[str, str]]:
        # Returns the list of (name, value) pairs in order
        return list(self._pairs)

# --- Request Dataclass ---

@dataclass
class Request:
    method: str
    target: str
    path: str
    query_string: str
    version: str
    headers: Headers
    body: bytes
    params: Dict[str, Any] = field(default_factory=dict)
    state: Dict[str, Any] = field(default_factory=dict)

    @property
    def query(self) -> Dict[str, List[str]]:
        # Query string split on &, empty pieces skipped. Each piece is name=value split at the first =, or just name with value ''.
        # '+' means space, '%XX' is percent-escape. Decoded as UTF-8.
        if not self.query_string:
            return {}

        result: Dict[str, List[str]] = {}

        for piece in self.query_string.split('&'):
            if not piece:
                continue

            parts = piece.split('=', 1)
            name_part = parts[0]
            value_part = parts[1] if len(parts) > 1 else ''

            # Custom decoding: '+' is space, standard URL decoding otherwise
            def decode_segment(segment: str) -> str:
                segment = segment.replace('+', ' ') # Handle '+' as space
                try:
                    # Use urllib.parse.unquote to handle %XX escapes
                    return urllib.parse.unquote(segment)
                except Exception as e:
                    # Should be caught by BadRequest during parse, but as a safeguard
                    raise BadRequest(f"Invalid percent-escape sequence: {segment}") from e

            try:
                name = decode_segment(name_part)
                value = decode_segment(value_part)
            except BadRequest as e:
                # Re-raise parsing error
                raise e
            except Exception as e:
                # Catch general decoding errors
                raise BadRequest(f"Decoding error in query string: {e}") from e

            if name not in result:
                result[name] = []
            result[name].append(value)

        return result

    @property
    def content_type(self) -> Tuple[str, Dict[str, str]]:
        # Parsed from the Content-Type header
        ct_header_value = self.headers.get("Content-Type")
        if not ct_header_value:
            return ('', {}) # Without header

        media_type: str = ''
        params: Dict[str, str] = {}

        parts = [p.strip() for p in ct_header_value.split(';')] # Split on semicolon

        # First piece is media type
        media_type = parts[0].lower()

        # Remaining pieces are parameters
        for part in parts[1:]:
            if not part:
                continue

            # Split on first '='
            param_parts = part.split('=', 1)
            name_part = param_parts[0].strip().lower()

            if len(param_parts) == 2:
                value_part = param_parts[1].strip()

                # Strip surrounding double quotes
                if value_part.startswith('"') and value_part.endswith('"'):
                    value = value_part[1:-1]
                else:
                    value = value_part

                # First occurrence of a name wins
                if name_part not in params:
                    params[name_part] = value
            # Pieces without '=' are skipped

        return (media_type, params)

    def text(self, charset: str = 'utf-8') -> str:
        # Decodes the body
        try:
            return self.body.decode(charset)
        except UnicodeDecodeError as e:
            raise BadRequest(f"Body decoding failed with charset '{charset}': {e}")

    def json(self) -> Any:
        # Parses text() as JSON
        try:
            return json.loads(self.text())
        except json.JSONDecodeError as e:
            raise BadRequest(f"Body is not valid JSON: {e}")

# --- Request Parsing Logic ---

def parse_request(data: bytes) -> Request:
    # 1. Split Head and Body
    try:
        head_bytes, body = data.split(b'\r\n\r\n', 1)
    except ValueError:
        # No CRLFCRLF found
        raise BadRequest("Request must contain headers terminated by \r\n\r\n")

    # 2. Parse Head (Headers and Request Line)
    head_lines = head_bytes.split(b'\r\n')

    if not head_lines or not head_lines[0]:
        raise BadRequest("Request head is empty")

    # 3. Parse Request Line
    try:
        request_line_parts = head_lines[0].decode('ISO-8859-1').split(' ')

        if len(request_line_parts) != 3:
            raise BadRequest("Request line must have Method, Target, and Version")

        method = request_line_parts[0].upper()
        target = request_line_parts[1]
        version = request_line_parts[2] # e.g., HTTP/1.1 or HTTP/1.0

        # Validation
        if not (method and method.isupper() and method.isalpha()):
            raise BadRequest("Invalid HTTP method")
        if not target.startswith('/'):
            raise BadRequest("Request target must start with /")
        if version not in ("HTTP/1.1", "HTTP/1.0"): # Only support 1.0 and 1.1 for now
             raise BadRequest("Unsupported HTTP version")

    except UnicodeDecodeError as e:
        # If the request line cannot be decoded as ISO-8859-1
        raise BadRequest(f"Request line decoding failed: {e}")
    except Exception as e:
        raise BadRequest(f"Error parsing request line: {e}")

    # 4. Parse Headers
    headers = Headers()
    header_lines = head_lines[1:]

    for line_bytes in header_lines:
        if not line_bytes:
            continue # Skip any empty lines that might appear before the final 


        try:
            line = line_bytes.decode('ISO-8859-1')
            # Check for obsolete line folding (starts with space or tab)
            if line[0].isspace():
                raise BadRequest("Obsolete line folding detected (line starting with whitespace)")

            # Header format: name:value
            if ':' not in line:
                raise BadRequest(f"Malformed header line: {line}")

            name, value = line.split(':', 1)

            # Remove surrounding spaces/tabs from value
            value = value.strip()

            # Add header (name case preserved, lookup case-insensitive)
            headers.add(name.strip(), value)

        except UnicodeDecodeError as e:
            raise BadRequest(f"Header line decoding failed: {e}")
        except Exception as e:
            # Catch issues during parsing (e.g., unexpected format)
            raise BadRequest(f"Error parsing header line: {e}")

    # 5. Body Parsing
    content_length = headers.get("Content-Length")
    transfer_encoding = headers.get("Transfer-Encoding")
    body = b''

    if transfer_encoding and transfer_encoding.lower() == 'chunked':
        # Chunked Encoding
        body_chunks = []
        remaining_data = body

        while remaining_data:
            # Read chunk size line
            try:
                # Chunk size can be hex, optionally followed by ; extension
                size_line, remainder = remaining_data.split(b'\r\n', 1)

                # Find the end of the size number (before potential ';')
                hex_size_str = size_line.split(b';', 1)[0].strip()
                chunk_size = int(hex_size_str, 16)

                # Read chunk body + trailing CRLF
                chunk_body_end = chunk_size + 2 # Size + CRLF
                if len(remainder) < chunk_body_end:
                    raise BadRequest("Incomplete chunk data")

                chunk_body = remainder[:chunk_size]
                remainder = remainder[chunk_size+2:]

                body_chunks.append(chunk_body)
                remaining_data = remainder

            except ValueError as e:
                raise BadRequest(f"Error parsing chunked encoding: {e}")
            except IndexError: # Should not happen if loop condition is correct
                break

        # Join chunks
        body = b''.join(body_chunks)

        # Trailer lines handling (ignored as per spec)
        # After the last chunk, there should be an empty line (b'\r\n') before trailers/end.
        # The loop above stops *after* reading the final 0 chunk size, which implies the next line is the empty line or trailers.
        # Since we only care about the body content, we stop here.
        pass # Body is constructed from chunks

    elif content_length is not None:
        # Content-Length Encoding
        try:
            cl = int(content_length)
        except ValueError:
            raise BadRequest("Content-Length header must be decimal digits only")

        if len(body) < cl:
            raise BadRequest(f"Body length mismatch. Expected {cl} bytes, got {len(body)}")

        # Check if any other Content-Length header exists (we only check the primary one found)
        # Note: The spec says 'several Content-Length fields must all hold the same value'.
        # Since we only parsed one, we trust it for now, assuming the caller/headers object handles duplicates if needed.

        body = body[:cl]

    else:
        # Neither header present, body is empty
        pass

    # 6. Final validation: Bytes left over after body must be zero
    # This is implicitly handled by how we split the initial data, assuming data = Head + Body + (optional leftover).
    # Since we split on the *first* \r\n\r\n, any bytes remaining after the expected body length must be an error.
    # If CL was used, the body was truncated/validated above. If Chunked, the loop consumed all relevant parts.
    # A simpler check is to ensure the initial data length matches (Head length + Body length).
    head_len = len(head_bytes)
    expected_total_len = head_len + len(body)
    if len(data) > expected_total_len:
        raise BadRequest("Bytes found after expected end of body")

    # 7. Return Request object
    return Request(
        method=method,
        target=target,
        path=target.lstrip('/') if target.startswith('/') else target, # Path is target before '?'
        query_string=target[target.find('?')+1:] if '?' in target else '',
        version=version,
        headers=headers,
        body=body
    )
from dataclasses import dataclass, field
from typing import Dict, List, Tuple, Optional, Any
