class DependencyGraph:
    """
    Records dependencies between cells.
    """
    def __init__(self):
        # Maps cell name to set of cells it refers to (precedents)
        self._precedents: dict[str, set[str]] = {}
        # Maps cell name to set of cells that refer to it (dependents)
        self._dependents: dict[str, set[str]] = {}
        # Internal state for cycle detection during traversal
        self._visiting: set[str] = set()
        self._visited: set[str] = set() # Fully processed
        self._cycle_cells: set[str] = set() # Final set of cycle cells

    def set_dependencies(self, cell: str, precedents: set[str]) -> None:
        """
        Replaces cell's precedents and updates dependents.
        """
        old_precedents = self._precedents.get(cell, set())

        # 1. Update precedents for 'cell'
        self._precedents[cell] = precedents

        # 2. Update dependents for all affected cells
        # Remove old dependent relationships
        for old_p in old_precedents - precedents:
            for dependent in self._dependents.get(old_p, set()):
                if dependent != cell:
                    self._dependents[dependent].discard(old_p)

        # Add new dependent relationships
        for new_p in precedents:
            self._dependents.setdefault(new_p, set()).add(cell)

    def precedents(self, cell: str) -> set[str]:
        """
        Returns the direct precedents (cells this cell refers to).
        """
        return self._precedents.get(cell, set())

    def dependents(self, cell: str) -> set[str]:
        """
        Returns the direct dependents (cells that refer to this cell).
        """
        return self._dependents.get(cell, set())

    def all_dependents(self, cell: str) -> set[str]:
        """
        Returns every cell that refers to 'cell' directly or through other cells.
        Includes 'cell' itself if 'cell' is on a cycle.
        """
        return self._recursive_dependents(cell, {cell})

    def _recursive_dependents(self, start_cell: str, current_set: set[str]) -> set[str]:
        """Helper for all_dependents using BFS/DFS approach for reachability.
        """
        queue = list(current_set)
        visited = set(current_set)

        while queue:
            current = queue.pop(0)
            for dependent in self.dependents.get(current, set()):
                if dependent not in visited:
                    visited.add(dependent)
                    queue.append(dependent)
        return visited

    def cycle_cells(self) -> set[str]:
        """
        Finds every cell that lies on a cycle using DFS.
        """
        self._visiting.clear()
        self._visited.clear()
        self._cycle_cells.clear()

        all_cells = set(self._precedents.keys()) | set(self._dependents.keys())

        for cell in all_cells:
            if cell not in self._visited:
                self._detect_cycles_dfs(cell)

        return self._cycle_cells

    def _detect_cycles_dfs(self, cell: str) -> None:
        """Recursive DFS helper for cycle detection.
        """
        self._visiting.add(cell)

        for precedent in self.precedents.get(cell, set()):
            if precedent in self._visiting:
                # Back edge found: Cycle detected! Mark all cells in the current stack path as cycle cells.
                # In this simplified structure, if we hit a cell in _visiting, it's part of a cycle.
                self._cycle_cells.add(cell)
                self._cycle_cells.add(precedent)
                # We don't need to fully trace the cycle here; marking them is sufficient for the engine.
            elif precedent not in self._visited:
                # Recurse deeper
                self._detect_cycles_dfs(precedent)
                # If the precedent is marked as a cycle cell, this cell is also part of the dependency chain leading to it.
                if precedent in self._cycle_cells:
                    self._cycle_cells.add(cell)

        self._visiting.remove(cell)
        self._visited.add(cell)
