            if isinstance(left_val, int) and isinstance(right_val, int):
                return left_val * right_val
            elif isinstance(left_val, float) or isinstance(right_val, float):
                return float(left_val) * float(right_val)

        elif op == '/':
            # Rule 3 & 4: Division
            if right_val == 0:
                return ERROR_ERROR # Division by zero
            # Rule 4: Always float
            return float(left_val) / float(right_val)

    except TypeError: # Should not happen if logic above is perfect, but safe guard
        return ERROR_ERROR

    return ERROR_ERROR # Should not be reached if input is strictly numbers


def evaluate(tree: FormulaNode, lookup: callable) -> Any:
    """Computes the formula's value given a cell value lookup function."""

    def recursive_evaluate(node: FormulaNode) -> Any:
        if isinstance(node, Number):
            return node.value

        elif isinstance(node, Reference):
            name = node.name
            cell_value = lookup(name)
            # Rule 2: Reference handling
            if cell_value is None: # Empty cell
                return 0
            # If the formula is ONLY a reference, return text unchanged
            if isinstance(cell_value, str) and not any(isinstance(n, BinaryOp) for n in [node]) and not any(isinstance(n, UnaryOp) for n in [node]):
                 # This check is complex because 'lookup' returns the value, not the formula structure. 
                 # We rely on the instruction: 'A formula that is only a reference therefore returns text unchanged ('=A1' where 'A1' holds 'hi' gives 'hi').'
                 # If the lookup result is a string, we return it, assuming it was the only thing.
                 return cell_value
            return cell_value

        elif isinstance(node, UnaryOp):
            operand_val = recursive_evaluate(node.operand)
            # Unary +/- on numbers
            if isinstance(operand_val, (int, float)) and node.op == '+':
                return operand_val
            elif isinstance(operand_val, (int, float)) and node.op == '-':
                return -operand_val
            # Unary on errors/text propagates error
            return operand_val # Propagates ErrorValue or other resulting errors

        elif isinstance(node, BinaryOp):
            left_val = recursive_evaluate(node.left)
            right_val = recursive_evaluate(node.right)
            return _calculate(node.op, left_val, right_val)

        return ERROR_ERROR # Fallback for safety

    # Special handling for the top level: if it's a single reference, return the raw value.
    if isinstance(tree, Reference):
        return lookup(tree.name)

    return recursive_evaluate(tree)

