def _cell_to_index(self, cell_name: str) -> tuple[int, int] | None:
    """Converts a cell name (e.g., 'A1') to (row_index, col_index). Returns None if out of bounds."""
    if not isinstance(cell_name, str) or not cell_name:
        return None

    import re
    match = re.match(r"([A-Z]+)([0-9]+)", cell_name)
    if not match:
        # This should ideally be caught earlier by validation, but handle defensively.
        return None

    col_str, row_str = match.groups()

    try:
        row = int(row_str) - 1  # 0-based row index
    except ValueError:
        # Should not happen if regex matched digits
        return None

    col_index = 0
    for char in col_str:
        col_index = col_index * 26 + (ord(char) - ord('A') + 1)

    # Check boundaries
    if 0 <= row < self.sheet.rows and 0 <= col_index < self.sheet.cols:
        return row, col_index
    else:
        # Cell is outside the sheet boundaries, return None
        return None
