import re
from typing import List, Optional, Dict, Any, Tuple
from collections import deque

# --- Error Values ---

class ErrorValue:
    """Base class for spreadsheet error values."""
    def __init__(self, code: str):
        self.code = code

    def __repr__(self) -> str:
        return f"ErrorValue('{self.code}')"

class DivByZeroError(ErrorValue):
    def __init__(self):
        super().__init__("#DIV/0!")

class ValueTypeError(ErrorValue):
    def __init__(self):
        super().__init__("#VALUE!")

class ReferenceError(ErrorValue):
    def __init__(self):
        super().__init__("#REF!")

class CycleError(ErrorValue):
    def __init__(self):
        super().__init__("#CYCLE!")

# Mapping of error codes to their instances for easy access
ERROR_VALUES: Dict[str, ErrorValue] = {
    "#DIV/0!": DivByZeroError(),
    "#VALUE!": ValueTypeError(),
    "#REF!": ReferenceError(),
    "#CYCLE!": CycleError(),
}

# --- Tokenization and Parsing Regexes ---

# Regex for cell references (e.g., A1, AA123). Allows for leading/trailing whitespace flexibility later.
REF_REGEX = re.compile(r"[A-Z]+\d+")

# Regex for function names (SUM, AVG, MIN, MAX) - case insensitive
FUNC_NAME_REGEX = re.compile(r"SUM|AVG|MIN|MAX", re.IGNORECASE)

# Regex components for parsing
NUMBER_REGEX = re.compile(r"[-+]?\b\d+(\.\d+)?\b")

# A more complex regex to capture expressions, calls, refs, and numbers.
# This simplified version aims to capture basic tokens for the recursive descent parser.
# It prioritizes grouping structures like calls, parentheses, or simple tokens.
# The full grammar will be parsed recursively, but this helps tokenization.
TOKEN_REGEX = re.compile(r"("[^"]*"| 
| \S+)")

# --- AST Nodes ---

class ASTNode:
    pass

class NumberNode(ASTNode):
    def __init__(self, value: float):
        self.value = value

    def __repr__(self) -> str:
        return f"Number({self.value})"

class RefNode(ASTNode):
    def __init__(self, cell_ref: str):
        self.cell_ref = cell_ref

    def __repr__(self) -> str:
        return f"Ref('{self.cell_ref}')"

class CallNode(ASTNode):
    def __init__(self, function_name: str, args: List[ASTNode]):
        self.function_name = function_name.upper()
        self.args = args

    def __repr__(self) -> str:
        arg_reprs = [repr(arg) for arg in self.args]
        return f"Call('{self.function_name}', {', '.join(arg_reprs)})"

class RangeNode(ASTNode):
    """Represents a range Ref1:Ref2."""
    def __init__(self, start_ref: str, end_ref: str):
        # Canonicalize the range: smaller cell reference comes first
        self.start_ref = start_ref
        self.end_ref = end_ref

    def __repr__(self) -> str:
        return f"Range('{self.start_ref}:{self.end_ref}')"

# --- Formula Parsing ---

class FormulaError(Exception):
    """Custom exception for formula parsing errors."""
    pass

class Parser:
    def __init__(self, formula_string: str):
        self.tokens: List[str] = self._tokenize(formula_string)
        self.pos = 0

    def _tokenize(self, formula_string: str) -> List[str]:
        """Splits the formula string into meaningful tokens."""
        # Simple split strategy: look for operators, function names, parentheses, and commas.
        # This is a placeholder for a full lexer, focusing on splitting based on structure.
        # We rely heavily on recursive descent for structure now.
        # For robust tokenization, a dedicated lexer is required, but for this context,
        # we rely on splitting by common delimiters while preserving structure for recursion.

        # Replace structural characters with spaces around them for easier splitting
        formula_string = formula_string.replace('(', ' ( ') 
        formula_string = formula_string.replace(')', ' ) ') 
        formula_string = formula_string.replace(',', ' , ') 
        formula_string = formula_string.replace(':', ' : ') # Crucial for range

        # Normalize whitespace and split
        tokens = [t.strip() for t in formula_string.split() if t.strip()]
        return tokens

    def peek(self) -> Optional[str]:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def consume(self, expected: Optional[str] = None) -> str:
        token = self.tokens[self.pos]
        if expected and token != expected:
            raise FormulaError(f"Expected '{expected}' but found '{token}' at position {self.pos}.")
        self.pos += 1
        return token

    def parse(self) -> ASTNode:
        """Entry point for parsing."""
        ast = self._parse_unary()
        if self.pos != len(self.tokens):
            raise FormulaError(f"Unexpected tokens remaining after parsing: {self.tokens[self.pos:]}")
        return ast

    # Grammar rules (simplified for demonstration, adhering to precedence)

    def _parse_primary(self) -> ASTNode:
        token = self.peek()
        if not token:
            raise FormulaError("Unexpected end of input.")

        # 1. Parenthesized expression
        if token == '(': 
            self.consume('(')
            expr = self._parse_unary()
            self.consume(')')
            return expr

        # 2. Reference
        if REF_REGEX.fullmatch(token):
            self.consume()
            return RefNode(token)

        # 3. Number
        if NUMBER_REGEX.fullmatch(token):
            self.consume()
            try:
                # Use float for consistency in number storage
                return NumberNode(float(token))
            except ValueError:
                raise FormulaError(f"Invalid number format: {token}")

        # 4. Function Call
        if FUNC_NAME_REGEX.fullmatch(token):
            return self._parse_call()

        # 5. Range (Ref:Ref) - Ranges are only allowed as function arguments
        if REF_REGEX.fullmatch(token) and self.tokens[self.pos+1] == ':':
            start_ref = self.consume()
            self.consume(':')
            end_ref = self.consume()
            return RangeNode(start_ref, end_ref)

        raise FormulaError(f"Unexpected token in primary expression: {token}")

    def _parse_call(self) -> CallNode:
        # Function name is already consumed if we reached here from the top level check
        func_token = self.tokens[self.pos-1]
        func_name = func_token
        self.consume()

        self.consume('(')
        args: List[ASTNode] = []

        # Check for empty argument list: func() -> FormulaError
        if self.peek() is not None and self.peek() != ')':
            # Parse arguments
            while True:
                arg_node = self._parse_arg()
                args.append(arg_node)

                # Check for next argument or closing parenthesis
                next_token = self.peek()
                if next_token == ',':
                    self.consume(',')
                else:
                    break

        self.consume(')')

        # Validation for function arguments count (e.g., MIN() is invalid, but SUM() might be valid if it aggregates zero items)
        if func_name.upper() in ("MIN", "MAX") and not args:
             raise FormulaError(f"{func_name} requires at least one argument.")

        return CallNode(func_name, args)

    def _parse_arg(self) -> ASTNode:
        # An argument is either a ref or an expr
        token = self.peek()
        if token is None:
            raise FormulaError("Expected argument but reached end of input.")

        # Check if the first token of the argument is a reference
        if REF_REGEX.fullmatch(token):
            # Single reference argument, treated as one-cell range
            self.consume()
            return RefNode(token)

        # Otherwise, it is an expression
        return self._parse_expression() # Use general expression parser for nested calls/math

    def _parse_expression(self) -> ASTNode:
        # This handles addition and subtraction (left-to-right evaluation)
        node = self._parse_unary()

        while self.peek() in ('+', '-'):
            op = self.consume()
            right = self._parse_unary()
            # In a real AST, we'd build an Expression node, but here we simplify to represent the operation
            # by returning a structure indicating the binary operation.
            return f"BinaryOp({repr(node)}, {op}, {repr(right)})".replace(' ', '')
            # NOTE: Real implementation would require a proper Expression/BinaryOp AST node.

        return node

    def _parse_unary(self) -> ASTNode:
        token = self.peek()
        if token == '+':
            self.consume('+')
            return self._parse_unary() # Unary plus
        if token == '-':
            self.consume('-')
            # Unary minus: Recursively parse the next element
            next_node = self._parse_unary()
            # Return a structure indicating negation
            return f"Negate({repr(next_node)})".replace(' ', '')

        return self._parse_primary()

