def _compute_aggregate(function_name: str, collected_numbers: List[float | int]) -> Any:
    """
    Computes the result for SUM, AVG, MIN, and MAX from a list of numbers.

    Args:
        function_name: The function name (e.g., 'SUM').
        collected_numbers: List of numbers collected from arguments.

    Returns:
        The computed result (float, int, or ErrorValue).
    """
    if not collected_numbers:
        if function_name == "SUM":
            return 0
        elif function_name == "AVG":
            return ERROR_VALUES["#DIV/0!"]
        elif function_name in ("MIN", "MAX"):
            return 0

    if function_name == "SUM":
        total = sum(collected_numbers)
        # Determine if the result should be an int or float
        if all(isinstance(n, int) for n in collected_numbers):
            return int(total)
        return float(total)

    elif function_name == "AVG":
        return sum(collected_numbers) / len(collected_numbers)

    elif function_name == "MIN":
        return min(collected_numbers)

    elif function_name == "MAX":
        return max(collected_numbers)

    # Should not happen if called correctly
    raise ValueError(f"Unknown aggregation function: {function_name}")

