# --- Parser Implementation ---

class RegexParser:
    def __init__(self, pattern: str):
        self.pattern = pattern
        self.pos = 0

    def _peek(self) -> str: 
        return self.pattern[self.pos] if self.pos < len(self.pattern) else ''

    def _consume(self, expected: str = None) -> str:
        char = self._peek()
        self.pos += 1
        if expected and char != expected:
            raise RegexError(f"Expected '{expected}' but found '{char}'", self.pos - 1)
        return char

    def parse(self) -> ASTNode:
        # Main recursive parsing function
        return self._parse_expression()

    def _parse_expression(self) -> ASTNode:
        # Parses an Alternation (OR) chain
        left = self._parse_term()

        while self._peek() == '|':
            self._consume('|')
            right = self._parse_term()

            # Collect options for the Alt node
            if isinstance(left, Alt): 
                left = Alt(left.options + (right,))
            else:
                left = Alt((left, right))

        return left

    def _parse_term(self) -> ASTNode:
        # Parses a concatenation sequence
        left = self._parse_factor()

        # Concatenation binds tighter than '|', so we keep consuming factors
        while self._peek() not in ['|', ')', ']'] and self._peek() not in ['*', '+', '?']:
            right = self._parse_factor()

            # Collect items for the Concat node
            if isinstance(left, Concat):
                left = Concat(left.items + (right,))
            else:
                left = Concat((left, right))

        return left

    def _parse_factor(self) -> ASTNode:
        # Parses the most basic unit: atom or grouped expression
        if self._peek() == '(': 
            start_pos = self.pos
            self._consume('(')
            node = self._parse_expression()

            if self._peek() != ')':
                raise RegexError(f"Unclosed parenthesis. Expected ')'", start_pos)

            self._consume(')')
            return Group(node)

        elif self._peek() == '[': 
            return self._parse_char_class()

        elif self._peek() == '\':
            return self._parse_escaped()

        else:
            # Must be a literal character or '.'
            char = self._peek()
            self._consume()
            if char == '.':
                return AnyChar()
            else:
                return Literal(char)

    def _parse_escaped(self) -> ASTNode:
        # Handles \x or 
        char = self._consume('\')
        if self.pos >= len(self.pattern):
            # Rule: A \ at the end of the pattern is an error.
            raise RegexError("Trailing backslash at end of pattern", self.pos - 1)

        next_char = self._peek()
        self._consume()

        # Per spec, \x means the next character is literal
        return Literal(next_char)

    def _parse_char_class(self) -> ASTNode:
        self._consume('[')
        start_pos = self.pos
        items: List[Tuple[str, str]] = []
        negated = False

        if self._peek() == '^':
            negated = True
            self._consume('^')

        while self._peek() != ']':
            low = self._peek()
            self._consume()

            if self._peek() == '-' and self.pos < len(self.pattern) and self.pattern[self.pos] != ']':
                # Range: low-high
                high = self._consume('-')
                self._consume()
                items.append((low, high))
            else:
                # Single character
                items.append((low, low))

        self._consume(']')

        if not items: 
            # Rule: An empty class [] / [^] is an error.
            raise RegexError("Empty character class", start_pos)

        return CharClass(tuple(items), negated)

    def apply_quantifier(self, node: ASTNode, quantifier: str) -> ASTNode:
        if not isinstance(node, (Literal, AnyChar, CharClass, Group)): 
            # Quantifiers apply to the atom just before them: a literal, '.', a class or a parenthesised group.
            raise RegexError(f"Quantifier '{quantifier}' applied to non-atom: {node}", self.pos - 1)

        self._consume(quantifier)

        if quantifier == '*':
            return Star(node)
        elif quantifier == '+':
            return Plus(node)
        elif quantifier == '?':
            return Optional(node)
        else:
            raise RegexError(f"Unknown quantifier: {quantifier}", self.pos - 1)

    def _parse_atom_with_quantifier(self, node: ASTNode) -> ASTNode:
        # Check for trailing quantifiers
        while self._peek() in ['*', '+', '?']:
            quantifier = self._peek()
            return self.apply_quantifier(node, quantifier)
        return node

    def _parse_factor(self) -> ASTNode:
        # Re-implementing factor logic to handle quantifiers immediately after atom
        if self._peek() == '(': 
            start_pos = self.pos
            self._consume('(')
            node = self._parse_expression()

            if self._peek() != ')':
                raise RegexError(f"Unclosed parenthesis. Expected ')'", start_pos)

            self._consume(')')
            # Group nodes do not inherently take quantifiers unless they are the whole factor, 
            # but per spec, quantifiers apply to the parenthesized group.
            return Group(node)

        elif self._peek() == '[': 
            node = self._parse_char_class()

        elif self._peek() == '\':
            node = self._parse_escaped()

        else:
            # Must be a literal character or '.'
            char = self._peek()
            self._consume()
            if char == '.':
                node = AnyChar()
            else:
                node = Literal(char)

        # Apply quantifiers immediately after parsing the atom
        return self._parse_atom_with_quantifier(node)

# --- Public Interface ---

def parse(pattern: str) -> ASTNode:
    """Parses a regex pattern string into an AST node."""
    if not pattern:
        return Empty()

    try:
        parser = RegexParser(pattern)
        ast = parser.parse()

        # Rule: An unclosed '(' is reported when the end of the pattern is reached.
        if parser.pos != len(pattern):
             # This catches cases where the expression finished early but there are leftover characters 
             # that weren't consumed by a valid structure (e.g., 'a(b' without a closing ')'
             # Although _parse_expression/term should catch unclosed groups, this is a safeguard.
             raise RegexError(f"Unexpected character '{pattern[parser.pos]}' after parsing", parser.pos)

        return ast
    except RegexError as e:
        raise e
    except Exception as e:
        # Catch any unforeseen parsing issues
        raise RegexError(f"Internal parsing error: {e}", 0)

