# --- NFA Matching Logic Implementation ---

# Helper function for state transition simulation
def transition(states: Set[State], char: str, transitions: Dict[State, Dict[str, List[State]]]) -> Set[State]:
    next_states = set()
    for state in states:
        if char in transitions.get(state, {}):
            for next_state in transitions[state][char]:
                next_states.add(next_state)
    return epsilon_closure(next_states, transitions)

