    current_states = epsilon_closure({nfa.start_state}, nfa.transitions)

    for char in text:
        # Compute the next set of states after consuming the character
        current_states = transition(current_states, char, nfa.transitions)
        if not current_states:
            return False

    # Match is successful if, after consuming all text, any active state is an accept state
    return bool(current_states.intersection(nfa.accept_states))

# Implementation of NFA.search(text, start=0) -> Optional[(i, j)]
def search(nfa: NFA, text: str, start: int = 0) -> Optional[Tuple[int, int]]:
    # We must check for an empty match first, as specified.
    # The state set after consuming zero characters starting at 'start'
    initial_states = epsilon_closure({nfa.start_state}, nfa.transitions)
    if initial_states.intersection(nfa.accept_states):
        # Empty match found at start position
        return (start, start)

    # Scan the rest of the text for the leftmost, longest match
    n = len(text)
    for i in range(start, n):
        # Reset states for a search starting at position i
        current_states = epsilon_closure({nfa.start_state}, nfa.transitions)
        match_found = False
        longest_match_end = i # Tracks the farthest end point reached

        for j in range(i, n):
            char = text[j]
            # Compute the next set of states
            current_states = transition(current_states, char, nfa.transitions)

            if not current_states:
                # No path forward from this point
                break

            # Check for acceptance at this position j+1
            if current_states.intersection(nfa.accept_states):
                match_found = True
                longest_match_end = j + 1

        # If a match was found starting at i, it is the leftmost match found so far
        if match_found:
            return (i, longest_match_end)

    return None

# Implementation of NFA.findall(text) -> List[str]
def findall(nfa: NFA, text: str) -> List[str]:
    results = []
    n = len(text)
    pos = 0
    while pos < n:
        # Find the leftmost match starting at or after 'pos'
        match_result = search(nfa, text, start=pos)

        if match_result is None:
            # No more matches found
            break

        i, j = match_result
        matched_string = text[i:j]
        results.append(matched_string)

        if j == i: # Empty match
            # Continue scanning from the next character
            pos = i + 1
        else: # Non-empty match
