# Global configuration for parsing
# ... (other constants remain the same)

class Parser:
    def __init__(self):
        self.scanner = Scanner()
        # State for duplicate key checking
        self.key_trackers: List[Dict[str, str]] = []

    def loads(self, text: str, duplicate_keys: str = 'last', max_depth: Optional[int] = None, allow_nan: bool = False) -> Any:
        """Parses a JSON string into a Python object.

        Args:
            text: The JSON string to parse.
            duplicate_keys: Policy for repeated object keys ('last', 'first', 'error').
            max_depth: Maximum nesting depth allowed (None for unlimited).
            allow_nan: Whether 'NaN', 'Infinity', '-Infinity' are parsed as float values.

        Returns:
            The parsed Python object.

        Raises:
            JSONError: On parsing errors, including depth violations.
            ValueError: If duplicate_keys is invalid or other structural errors occur.
        """
        self.key_trackers = []
        try:
            # Scanner must be updated to accept allow_nan
            tokens = self.scanner.tokenize(text, allow_nan=allow_nan)
            # Initial depth is 1 for the outermost structure (object/array)
            return self._parse_value(tokens, max_depth, duplicate_keys, allow_nan, current_depth=1)
        except JSONError as e:
            raise e
        except ValueError as e:
            raise ValueError(f"JSON parsing error: {e}")

    def _parse_value(self, tokens: List[Token], max_depth: Optional[int], duplicate_keys: str, allow_nan: bool, current_depth: int) -> Any:
        token = tokens.pop(0)

        # Depth check before proceeding to complex types (Object/Array)
        if max_depth is not None and current_depth > max_depth:
            # We need to signal the error here. In a full implementation, we would use the token's location.
            raise JSONError(f"Nesting depth limit ({max_depth}) exceeded.", token.line, token.column)

        if token.type == TokenType.STRING:
            # Handle string values
            return token.value
        elif token.type == TokenType.NUMBER:
            if allow_nan:
                if token.value.lower() in ('nan', 'infinity', '-infinity'):
                    try:
                        return float(token.value)
                    except ValueError:
                        # Should not happen if scanner is correct, but for safety
                        pass

            # Standard number parsing
            try:
                return float(token.value) if '.' in token.value or 'e' in token.value.lower() else int(token.value)
            except ValueError:
                raise JSONError(f"Invalid number format: {token.value}", token.line, token.column)
        elif token.type == TokenType.TRUE:
            return True
        elif token.type == TokenType.FALSE:
            return False
        elif token.type == TokenType.NULL:
            return None
        elif token.type == TokenType.OBJECT:
            # Start parsing object
            obj_data = self._parse_object(tokens, max_depth, duplicate_keys, allow_nan, current_depth)
            return obj_data
        elif token.type == TokenType.ARRAY:
            # Start parsing array
            arr_data = self._parse_array(tokens, max_depth, duplicate_keys, allow_nan, current_depth)
            return arr_data
        else:
            raise JSONError(f"Unexpected token type: {token.type.name} ({token.value})", token.line, token.column)

    def _parse_object(self, tokens: List[Token], max_depth: Optional[int], duplicate_keys: str, allow_nan: bool, current_depth: int) -> Dict[str, Any]:
        obj = {}
        key_tracker = {}
        self.key_trackers.append(key_tracker)

        while tokens and tokens[0].type == TokenType.STRING:
            key_token = tokens.pop(0)
            key = key_token.value

            # 1. Handle duplicate keys
            if key in key_tracker:
                if duplicate_keys == 'error':
                    # Raise error pointing at the opening quote of the repeated key
                    raise JSONError(f"Duplicate key found: '{key}'. Policy 'error' enforced.", key_token.line, key_token.column)
                elif duplicate_keys == 'first':
                    continue # Ignore subsequent values
                elif duplicate_keys == 'last':
                    pass # Overwrite (default behavior)
            else:
                key_tracker[key] = True

            # Expect ':' token
            if not tokens or tokens[0].type != TokenType.COLON:
                raise JSONError("Expected ':' after key.", tokens[0].line, tokens[0].column) # Use current token location if available
            tokens.pop(0) # Consume ':'

            # Parse value (depth increases for value parsing)
            value = self._parse_value(tokens, max_depth, duplicate_keys, allow_nan, current_depth + 1)
            obj[key] = value

        # Expect closing '}'
        if not tokens or tokens[0].type != TokenType.RBRACE:
            raise JSONError("Expected '}' to close object.", tokens[0].line, tokens[0].column)
        tokens.pop(0) # Consume '}'

        self.key_trackers.pop() # Backtrack key tracker
        return obj

    def _parse_array(self, tokens: List[Token], max_depth: Optional[int], duplicate_keys: str, allow_nan: bool, current_depth: int) -> List[Any]:
        arr = []

        while tokens and tokens[0].type != TokenType.RBRACKET:
            # Parse value (depth increases for value parsing)
            value = self._parse_value(tokens, max_depth, duplicate_keys, allow_nan, current_depth + 1)
            arr.append(value)

            # Expect comma or closing bracket
            if tokens and tokens[0].type == TokenType.COMMA:
                tokens.pop(0) # Consume ','
            elif tokens and tokens[0].type != TokenType.RBRACKET:
                 raise JSONError("Expected ',' or ']' in array.", tokens[0].line, tokens[0].column)

        # Expect closing ']' 
        if not tokens or tokens[0].type != TokenType.RBRACKET:
            raise JSONError("Expected ']' to close array.", tokens[0].line, tokens[0].column)
        tokens.pop(0) # Consume ']'
        return arr

