            is_satisfied = self._check_operator(op, ref, v)
            if not is_satisfied:
                return False
        return True

    def _check_operator(self, op: str, ref: Version, v: Version) -> bool:
        # Helper to check a single constraint
        if op == "==":
            return v == ref
        elif op == "!=":
            return v != ref
        elif op == ">":
            return v > ref
        elif op == "<":
            return v < ref
        elif op == "=": # Should be covered by == but for completeness
             return v == ref
        elif op == ">=":
            return v >= ref
        elif op == "<=":
            return v <= ref
        elif op == "^":
            # Caret constraint (^MAJOR.MINOR.PATCH) means >= X.Y.Z and < (X+1).0.0 or < X.Y+1.0 if Y != 0, or < X.0+1.0 if Y=0
            # Simplified logic based on typical semantic versioning interpretation:
            # ^1.2.3 is >=1.2.3 and <2.0.0
            # ^0.2.3 is >=0.2.3 and <0.3.0
            # ^0.0.3 is >=0.0.3 and <0.0.4

            if ref.major > 0:
                upper_bound = Version(f"{ref.major + 1}.0.0")
            elif ref.major == 0 and ref.minor > 0:
                upper_bound = Version(f"0.{ref.minor + 1}.0")
            elif ref.major == 0 and ref.minor == 0 and ref.patch > 0:
                upper_bound = Version(f"0.0.{ref.patch + 1}")
            elif ref.major == 0 and ref.minor == 0 and ref.patch == 0:
                 # ^0.0.0 is >=0.0.0, <0.0.1
                 upper_bound = Version("0.0.1")
            else:
                # Should not happen for valid versions
                return False

            return v >= ref and v < upper_bound

        elif op == "~":
            # Tilde constraint (~MAJOR.MINOR.PATCH) means >= X.Y.Z and < X.(Y+1).0
            if ref.major == 0 and ref.minor == 0 and ref.patch == 0:
                # ~0.0.0 is >=0.0.0, <0.0.1
                upper_bound = Version("0.0.1")
            elif ref.major == 0 and ref.minor == 0:
                # ~0.0.3 is >=0.0.3, <0.0.4
                upper_bound = Version(f"0.0.{ref.patch + 1}")
            elif ref.major == 0: # X=0, Y>0
                # ~0.2.3 is >=0.2.3, <0.3.0
                upper_bound = Version(f"0.{ref.minor + 1}.0")
            else: # X>0
                # ~1.2.3 is >=1.2.3, <1.3.0
                upper_bound = Version(f"{ref.major}.{ref.minor + 1}.0")

            return v >= ref and v < upper_bound

        return False

    def __str__(self) -> str:
        # Returns the spec with all whitespace removed
        spec_parts = []
        for op, ref in self.constraints:
            if op == '*':
                spec_parts.append('*')
            else:
                spec_parts.append(f"{op}{ref}")
        return "{','.join(spec_parts)}"

    def __repr__(self):
        return f"Range('{self.__str__()}')"

