        if not requires: # Handle case where there are no dependencies
            # Check if version is valid even if it has no requirements
            Version(version)
        else:
            # Validate all requirement specs
            for dep_name, spec in requires.items():
                try:
                    Range(spec)
                except ValueError as e:
                    raise ValueError(f"Invalid range spec '{spec}' for dependency '{dep_name}': {e}")

        # Check for existing release
        if name in self._releases and version in self._releases[name]:
            raise ValueError(f"Version {version} of package {name} already exists in the index.")

        # Add release
        self._releases[name][version] = requires

    def versions(self, name: str) -> list[Version]:
        """Returns a list of known Version objects for a given package, newest first.
        """
        if name not in self._releases:
            return []

        # Get version strings, convert to Version objects, and sort descending
        version_strings = list(self._releases[name].keys())
        versions = [Version(v) for v in version_strings]
        versions.sort(reverse=True)
        return versions

    def requirements(self, name: str, version: Version) -> dict[str, Range]:
        """Returns a dict mapping each dependency name to its Range for a specific Version.
        Raises KeyError if the version is not known for that package.
        """
        if name not in self._releases:
            raise KeyError(f"Package {name} not found in index.")

        version_str = str(version)
        if version_str not in self._releases[name]:
            raise KeyError(f"Version {version_str} of package {name} not found in index.")

        return self._releases[name][version_str]

    @classmethod
    def from_dict(cls, data: dict) -> 'PackageIndex':
        """Builds an index from a dictionary structure.
        Data format: {name: {version_str: {dep: spec, ...}, ...}, ...}
        """
        index = cls()
        for name, versions_data in data.items():
            if not isinstance(versions_data, dict):
                raise ValueError(f"Data for package {name} must be a dictionary of versions.")

            for version_str, requirements_data in versions_data.items():
                if not isinstance(requirements_data, dict):
                    raise ValueError(f"Requirements for {name}@{version_str} must be a dictionary of dependencies.")

                try:
                    # Validate version
                    Version(version_str)

                    # Validate all requirement specs
                    processed_requirements = {}
                    for dep_name, spec in requirements_data.items():
                        try:
