                            processed_requirements[dep_name] = Range(spec)
                        except ValueError as e:
                            raise ValueError(f"Failed to parse version '{spec}' for {name}@{version_str} dependency '{dep_name}' in dict: {e}")

                    index._releases[name][version_str] = processed_requirements
                except ValueError as e:
                    raise ValueError(f"Failed to parse version '{version_str}' for {name} in dict: {e}")

