import re

class Version:
    """Represents a version in MAJOR.MINOR.PATCH format."""

    _VERSION_PATTERN = re.compile(r"^([0-9]+)\.([0-9]+)\.([0-9]+)$")

    def __init__(self, text: str):
        match = self._VERSION_PATTERN.match(text)
        if not match:
            raise ValueError(f"Invalid version format: '{text}'. Expected MAJOR.MINOR.PATCH.")

        parts = [int(p) for p in match.groups()]
        self.major, self.minor, self.patch = parts

    def __hash__(self):
        return hash((self.major, self.minor, self.patch))

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return (self.major, self.minor, self.patch) == (other.major, other.minor, other.patch)

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return (self.major, self.minor, self.patch) < (other.major, other.minor, other.patch)

    def __le__(self, other):
        return self < other or self == other

    def __gt__(self, other):
        return self > other or self == other

    def __ge__(self, other):
        return self > other or self == other

    def __str__(self) -> str:
        return f"{self.major}.{self.minor}.{self.patch}"

    @property
    def major(self) -> int:
        return self._major

    @property
    def minor(self) -> int:
        return self._minor

    @property
    def patch(self) -> int:
        return self._patch

    # Cache attributes for fast access, though they are immutable after init
    _major = None
    _minor = None
    _patch = None

    def __setattr__(self, name, value):
        if hasattr(self, 'major') and name in ('major', 'minor', 'patch'):
             # Prevent accidental overwriting of the tuple components if we were to add setters
             pass 
        super().__setattr__(name, value)

# Add properties after init to ensure they are set
Version.major = property(lambda self: self.major)
Version.minor = property(lambda self: self.minor)
Version.patch = property(lambda self: self.patch)
class Range:
    """Represents a version range spec.
    """

    def __init__(self, spec: str):
        # Clean up spec: remove whitespace
        cleaned_spec = spec.strip()

        if not cleaned_spec:
            raise ValueError("Range spec cannot be empty.")

        self.constraints = []

        # Regex to capture constraint: [operator]VERSION or '*' or [operator]VERSION
        # Operators: ==, !=, >=, <=, >, <, ^, ~
        constraint_pattern = re.compile(r"(==|!=|>=|<=|>|<|\^|~)?([0-9]+\.[0-9]+\.[0-9]+)" )

        constraints = [c.strip() for c in cleaned_spec.split(',')] 

        for constraint in constraints:
            constraint = constraint.strip()

            # Handle '*' wildcard
            if constraint == "*":
                self.constraints.append(('*', None)) # '*' constraint
                continue

            # Check for explicit operators first
            match = re.match(r"(==|!=|>=|<=|>|<)(.+)", constraint)
            if match:
                op = match.group(1)
                version_text = match.group(2).strip()
                try:
                    version = Version(version_text)
                    self.constraints.append((op, version))
                except ValueError as e:
                    raise ValueError(f"Invalid version in constraint '{constraint}': {e}")
                continue

            # Handle prefix operators (^, ~)
            if constraint.startswith("~"):
                op = "~"
                version_text = constraint[1:].strip()
            elif constraint.startswith("^"):
                op = "^"
                version_text = constraint[1:].strip()
            else:
                # If no operator and not '*', it must be '==' implicitly, but spec requires explicit operator or '*'
                raise ValueError(f"Unknown operator or format in constraint: '{constraint}'")

            try:
                version = Version(version_text)
                self.constraints.append((op, version))
            except ValueError as e:
                raise ValueError(f"Invalid version in constraint '{constraint}': {e}")

    def contains(self, v: Version) -> bool:
        """Checks if the given Version satisfies all constraints in this Range.
        """
        for op, ref in self.constraints:
            if op == '*':
                continue # '*' matches everything

            # Check basic operator satisfaction
            is_satisfied = self._check_operator(op, ref, v)
            if not is_satisfied:
                return False
        return True

    def _check_operator(self, op: str, ref: Version, v: Version) -> bool:
        # Helper to check a single constraint
        if op == "==":
            return v == ref
        elif op == "!=":
            return v != ref
        elif op == ">":
            return v > ref
        elif op == "<":
            return v < ref
        elif op == "=": # Should be covered by == but for completeness
             return v == ref
        elif op == ">=":
            return v >= ref
        elif op == "<=":
            return v <= ref
        elif op == "^":
            # Caret constraint (^MAJOR.MINOR.PATCH) means >= X.Y.Z and < (X+1).0.0 or < X.Y+1.0 if Y != 0, or < X.0+1.0 if Y=0
            # Simplified logic based on typical semantic versioning interpretation:
            # ^1.2.3 is >=1.2.3 and <2.0.0
            # ^0.2.3 is >=0.2.3 and <0.3.0
            # ^0.0.3 is >=0.0.3 and <0.0.4

            if ref.major > 0:
                upper_bound = Version(f"{ref.major + 1}.0.0")
            elif ref.major == 0 and ref.minor > 0:
                upper_bound = Version(f"0.{ref.minor + 1}.0")
            elif ref.major == 0 and ref.minor == 0 and ref.patch > 0:
                upper_bound = Version(f"0.0.{ref.patch + 1}")
            elif ref.major == 0 and ref.minor == 0 and ref.patch == 0:
                 # ^0.0.0 is >=0.0.0, <0.0.1
                 upper_bound = Version("0.0.1")
            else:
                # Should not happen for valid versions
                return False

            return v >= ref and v < upper_bound

        elif op == "~":
            # Tilde constraint (~MAJOR.MINOR.PATCH) means >= X.Y.Z and < X.(Y+1).0
            if ref.major == 0 and ref.minor == 0 and ref.patch == 0:
                # ~0.0.0 is >=0.0.0, <0.0.1
                upper_bound = Version("0.0.1")
            elif ref.major == 0 and ref.minor == 0:
                # ~0.0.3 is >=0.0.3, <0.0.4
                upper_bound = Version(f"0.0.{ref.patch + 1}")
            elif ref.major == 0: # X=0, Y>0
                # ~0.2.3 is >=0.2.3, <0.3.0
                upper_bound = Version(f"0.{ref.minor + 1}.0")
            else: # X>0
                # ~1.2.3 is >=1.2.3, <1.3.0
                upper_bound = Version(f"{ref.major}.{ref.minor + 1}.0")

            return v >= ref and v < upper_bound

        return False

    def __str__(self) -> str:
        # Returns the spec with all whitespace removed
        spec_parts = []
        for op, ref in self.constraints:
            if op == '*':
                spec_parts.append('*')
            else:
                spec_parts.append(f"{op}{ref}")
        return "{','.join(spec_parts)}"

    def __repr__(self):
        return f"Range('{self.__str__()}')"

