                 raise SaveError(f"Unlocked exit ({room_id}, {direction}) is not a properly defined locked exit.")

        if not isinstance(self.visited_rooms, set):
             raise SaveError("Invalid format for 'visited' list in version 2 save.")

        if not isinstance(self.scored_items, set):
            raise SaveError("Invalid format for 'scored' list in version 2 save.")

        if not isinstance(self.score, int) or self.score < 0:
            raise SaveError("Invalid 'score' value in version 2 save: must be a non-negative integer.")

    elif version == 1:
        # Version 1: Legacy save, no new state
        self.unlocked_exits = []
        # Start room is always visited, current room is visited
