import posixpath

def normalize(path: str, cwd: str = '/') -> str:
    """
    Returns an absolute path with no . or .. parts, no repeated /, and no trailing / (except the root, /).
    A relative path is taken relative to cwd (an absolute normalised path).
    """
    if not path: 
        raise ValueError("Path cannot be empty")

    # Resolve relative path against cwd
    if not path.startswith('/'):
        path = posixpath.join(cwd, path)

    # Convert to list of components and process '..' and '.'
    parts = [p for p in path.split('/') if p and p != '.']

    new_parts = []
    for part in parts:
        if part == '..':
            if new_parts: # Do not go above root
                new_parts.pop()
        else:
            new_parts.append(part)

    # Reconstruct the path
    normalized_path = posixpath.join('/', *new_parts)

    # Ensure root path '/' is not represented as empty string if parts was empty
    if not normalized_path.startswith('/'):
        normalized_path = '/' # Should not happen with posixpath.join('/', *new_parts) but as a safeguard

    # Handle trailing slash for root case
    if normalized_path == '/':
        return '/' # Keep root as is

    return normalized_path

def join(base: str, *parts: str) -> str:
    """
    Joins paths like posixpath.join. A part starting with '/' starts over.
    Returns the result normalised.
    """
    # If the base is absolute, we treat it as the starting point
    if base.startswith('/'):
        # Start with base, then join parts
        return normalize(posixpath.join(base, *parts))
    else:
        # If base is relative (which shouldn't happen much here, but for robustness),
        # we assume it's relative to root for joining purposes.
        return normalize(posixpath.join('/', base, *parts))

def split(path: str) -> tuple[str, str]:
    """
    Takes an absolute normalised path and returns (parent, name);
    split('/') is ('/', '').
    """
    # Path must be absolute and normalised
    if not path.startswith('/'):
        raise ValueError("Path must be absolute and normalised for splitting")

    if path == '/':
        return ('/', '')

    # Remove trailing slash if present (though normalize should prevent this for non-root)
    path_stripped = path.rstrip('/')

    # Find the last slash
    last_slash_index = path_stripped.rfind('/')

    if last_slash_index == 0:
        # Case: '/name' -> parent is '/', name is 'name'
        return ('/', path_stripped[1:])
    elif last_slash_index == -1:
        # This case implies path was just a filename without leading '/', which violates assumption
        return ('/', path_stripped)
    else:
        parent = path_stripped[:last_slash_index]
        name = path_stripped[last_slash_index+1:]
        return (parent, name)

def is_within(path: str, ancestor: str) -> bool:
    """
    Tells whether the normalised path is ancestor itself or lies below it.
    /ab is not within /a.
    """
    if path == ancestor:
        return True

    # Check if path starts with ancestor followed by '/' (i.e., is a subdirectory)
    return path.startswith(ancestor + '/')

