from dataclasses import dataclass, field
from typing import Dict, List, Optional, Union
import decimal
import math

# Set precision high enough for percentage calculations
decimal.getcontext().prec = 50


# --- Utility Functions ---

def parse_amount(text: str) -> int:
    """Accepts digits optionally followed by '.' and one or two digits, and returns the amount in cents.
    Raises ValueError for invalid input.
    """
    if not isinstance(text, str):
        raise ValueError("Amount must be a string.")
    try:
        # Use Decimal for robust parsing, then convert to cents (integer)
        d = decimal.Decimal(text)
        # Multiply by 100 and round to nearest integer to get cents
        return int(round(d * 100))
    except decimal.InvalidOperation:
        raise ValueError(f"Invalid amount format: {text}")


def format_amount(cents: int) -> str:
    """Returns the amount as a string with exactly two decimals.
    """
    # Use Decimal for precise formatting
    d = decimal.Decimal(cents)
    # Format to two decimal places, ensuring correct sign handling
    return f"{d:.2f}"


# --- Split Types ---

@dataclass(frozen=True)
class Equal:
    members: Optional[List[str]] = None

@dataclass(frozen=True)
class Exact:
    shares: Dict[str, int]

@dataclass(frozen=True)
class Percent:
    shares: Dict[str, Union[int, decimal.Decimal, str]]


# --- Expense Model ---

@dataclass(frozen=True)
class Expense:
    description: str
    paid_by: str
    amount: int  # In cents
    split: Union[Equal, Exact, Percent]


# --- Group Model ---

@dataclass
class Group:
    members: List[str]
    expenses: List[tuple[Expense, Dict[str, int]]] = field(default_factory=list)
    payments: List[tuple[str, str, int]] = field(default_factory=list)

    def add_member(self, name: str):
        if name in self.members:
            raise ValueError(f"Member '{name}' is already in the group.")
        self.members.append(name)

    def add_expense(self, expense: Expense) -> Dict[str, int]:
        if expense.amount <= 0:
            raise ValueError("Expense amount must be positive.")

        # 1. Validation
        if expense.paid_by not in self.members:
            raise ValueError(f"Payer '{expense.paid_by}' is not a member of the group.")

        split_type = type(expense.split)
        if split_type == Exact:
            shares = expense.split.shares
            if not all(m in self.members for m in shares):
                raise ValueError("All members in Exact split must be group members.")
            if not all(s >= 0 for s in shares.values()):
                raise ValueError("All Exact shares must be non-negative.")
            if sum(shares.values()) != expense.amount:
                raise ValueError("Exact shares must sum up exactly to the expense amount.")
            # Return shares in group member order
            ordered_shares = {member: shares[member] for member in self.members if member in shares}
            return ordered_shares

        elif split_type == Equal:
            if not expense.split.members:
                # Share equally among all group members
                participants = self.members
            else:
                # Share equally among specified members
                participants = expense.split.members

            if not participants:
                 raise ValueError("Equal split must specify members or apply to all members.")

            if not all(p in self.members for p in participants):
                 raise ValueError("All specified members in Equal split must be group members.")
            if len(set(participants)) != len(participants):
                 raise ValueError("Equal split members must be unique.")

            n = len(participants)
            base_share = expense.amount // n
            remainder = expense.amount % n

            shares: Dict[str, int] = {p: base_share for p in participants}

            # Distribute remainder to first participants in alphabetical order
            sorted_participants = sorted(participants)
            for i in range(remainder):
                shares[sorted_participants[i]] += 1

            return shares

        elif split_type == Percent:
            shares_dict = expense.split.shares
            total_percent = 0

            # Validate shares
            for member, percent_val in shares_dict.items():
                try:
                    # Convert various types to Decimal for reliable summing and validation
                    if isinstance(percent_val, str):
                        percent_val = decimal.Decimal(percent_val)
                    elif isinstance(percent_val, int): 
                        percent_val = decimal.Decimal(percent_val)
                    elif isinstance(percent_val, decimal.Decimal): 
                        pass
                    else: raise TypeError("Percentage must be int, Decimal, or str.")

                    if percent_val < 0:
                        raise ValueError

                    if member not in self.members:
                         raise ValueError

                    total_percent += percent_val
                except Exception:
                    raise ValueError(f"Invalid percentage share for {member}.")

            if total_percent != decimal.Decimal('100'):
                raise ValueError(f"Percentages must sum exactly to 100, got {total_percent}.")

            # Calculate shares using Decimal for exact intermediate calculation
            calculated_shares: Dict[str, decimal.Decimal] = {}
            for member, percent_val in shares_dict.items():
                # Calculate floor(Amount * Percentage / 100)
                share_decimal = (decimal.Decimal(expense.amount) * percent_val) / decimal.Decimal('100')
                calculated_shares[member] = math.floor(float(share_decimal))

            total_calculated_share = sum(calculated_shares.values())
            missing_amount = expense.amount - total_calculated_share

            # Distribute missing cents based on largest fractional part
            remainders: List[tuple[float, str]] = []
            for member, percent_val in shares_dict.items():
                share_decimal = (decimal.Decimal(expense.amount) * percent_val) / decimal.Decimal('100')
                fractional_part = share_decimal - decimal.Decimal(math.floor(float(share_decimal)))
                # Use negative fractional part for sorting stability, tie-break alphabetically
                remainders.append((-fractional_part, member))

            # Sort: largest fractional part first (smallest negative value), then alphabetically
            remainders.sort()

            # Add missing cents one by one
            final_shares: Dict[str, int] = {member: int(math.floor(float(share_decimal))) for member, share_decimal in calculated_shares.items()}

            for i in range(missing_amount):
                # Apply to the member with the largest remainder (first in sorted list)
                member_to_boost = remainders[i % len(remainders)][1]
                final_shares[member_to_boost] += 1

            # Final check to ensure shares sum up correctly
            if sum(final_shares.values()) != expense.amount:
                 # This should theoretically not happen with the logic above but is a safeguard
                 raise RuntimeError("Internal share calculation error: shares do not sum to total amount.")

            # Return shares in group member order
            ordered_shares = {member: final_shares[member] for member in self.members if member in final_shares}
            return ordered_shares

        else:
            raise TypeError("Unsupported split type.")

    def add_payment(self, payer: str, payee: str, amount: int):
        if payer not in self.members or payee not in self.members:
            raise ValueError("Payer or payee must be a member of the group.")
        if amount <= 0:
            raise ValueError("Payment amount must be positive.")
        self.payments.append((payer, payee, amount))


# --- Group Loading Utility ---

def load_group(data: dict) -> 'Group':
    """Builds a Group from a dictionary structure.
    """
    members: List[str] = data.get("members", [])
    group = Group(members=members)

    # Process Expenses
    for exp_data in data.get("expenses", []):
        description = exp_data["description"]
        paid_by = exp_data["paid_by"]
        amount_str = exp_data["amount"]
        split_data = exp_data["split"]

        amount_cents = parse_amount(amount_str)
        expense = Expense(description, paid_by, amount_cents, None)

        # Determine split object
        split_type = split_data.get("type")
        if split_type == "equal":
            members = split_data.get("members")
            expense.split = Equal(members=members)
        elif split_type == "percent":
            shares = split_data.get("shares", {})
            # Convert string percentages to Decimal if necessary for Percent class
            percent_shares: Dict[str, Union[int, decimal.Decimal, str]] = {}
            for k, v in shares.items():
                if isinstance(v, str):
                    try:
                        v = decimal.Decimal(v)
                    except decimal.InvalidOperation:
                        pass # Keep as string if Decimal conversion fails, let Percent handle it
                percent_shares[k] = v
            expense.split = Percent(shares=percent_shares)
        elif split_type == "exact":
            shares = split_data.get("shares", {})
            # Ensure exact shares are ints if possible, though they might come in as strings
            int_shares: Dict[str, int] = {}
            for k, v in shares.items():
                try:
                    int_shares[k] = int(round(decimal.Decimal(str(v))))
                except:
                    raise ValueError(f"Exact share for {k} must be a valid number string.")
            expense.split = Exact(shares=int_shares)
        else:
            raise ValueError(f"Unknown split type: {split_type}")

        # Calculate and store shares
        shares_dict = group.add_expense(expense)
        group.expenses.append((expense, shares_dict))

    # Process Payments
    for pay_data in data.get("payments", []):
        payer = pay_data["from"]
        payee = pay_data["to"]
        amount_str = pay_data["amount"]
        amount_cents = parse_amount(amount_str)
        group.add_payment(payer, payee, amount_cents)

    return group


# --- Split Definitions ---

