# --- Utility Functions ---

def parse_amount(text: str) -> int:
    """Accepts digits optionally followed by '.' and one or two digits, and returns the amount in cents.
    Raises ValueError if the input format is invalid.
    """
    if not isinstance(text, str):
        raise ValueError(f"Amount must be a string, got {type(text).__name__}")

    # Regex to match integers, or optionally digits.digits (up to two decimal places)
    match = re.fullmatch(r'([+-]?)(\d+)(\.\d{1,2})?', text)
    if not match:
        raise ValueError(f"Invalid amount format: '{text}'. Expected format like '12', '12.5', or '0.05'.")

    sign = -1 if match.group(1) == '-' else 1
    integer_part = int(match.group(2))
    decimal_part_str = match.group(3) or '00'

    cents = integer_part * 100
    if decimal_part_str:
        # Scale by 100 and convert to integer, handling cases like '12.5' (50 cents) vs '12.50' (50 cents)
        decimal_value = int(decimal_part_str.replace('.', ''))
        # Since the regex ensures 1 or 2 digits after '.', we just need to handle the shift
        if len(decimal_part_str) == 3: # Should not happen with regex, but for safety
             cents += decimal_value // 10
        elif len(decimal_part_str) == 2:
             cents += decimal_value
        elif len(decimal_part_str) == 1:
             cents += decimal_value * 10
        # A simpler way, relying on float conversion and rounding to cents, but since we want exactness:
        # We rely on the regex match: if it matched, it's safe to calculate.
        # Since the regex ensures only 1 or 2 digits, we multiply the fractional part by 100 and take floor/int.
        fractional_value = int(float(decimal_part_str) * 100)
        cents = (integer_part * 100) + fractional_value

    return cents * sign

def format_amount(cents: int) -> str:
    """Returns the amount as a string with exactly two decimals, using '-' for negative amounts.
    """
    if cents >= 0:
        amount_float = cents / 100.0
        return f"{amount_float:.2f}"
    else:
        # Handle negative amounts: convert to positive, format, then prepend '-' 
        positive_cents = abs(cents)
        amount_float = positive_cents / 100.0
        return f"-{amount_float:.2f}"


# --- Splits ---

@dataclass(frozen=True)
class Equal:
    """Shared equally among listed members or all group members.
    """
    members: Optional[List[str]] = None

@dataclass(frozen=True)
class Exact:
    """Shares defined by exact cents per member.
    """
    shares: Dict[str, int]

    def __post_init__(self):
        total_shares = sum(self.shares.values())
        if total_shares != 0: # Check for zero total, though expense amount > 0 check handles this indirectly
             raise ValueError("Exact shares must sum to the expense amount.")
        for member, share in self.shares.items():
            if share < 0:
                raise ValueError(f"Exact share for {member} cannot be negative.")

@dataclass(frozen=True)
class Percent:
    """Shares defined by percentage per member.
    """
    shares: Dict[str, Union[int, str, decimal.Decimal]]

    def __post_init__(self):
        total_percentage = 0
        for percentage in self.shares.values():
            if isinstance(percentage, (int, decimal.Decimal)): 
                total_percentage += int(percentage)
            else: # Must be string
                try:
                    total_percentage += int(decimal.Decimal(percentage))
                except decimal.InvalidOperation:
                    raise ValueError(f"Invalid percentage format: {percentage}")

        # For validation, we must check the sum is exactly 100. Since percentages can be Decimal or str, we calculate carefully.
        decimal_sum = decimal.Decimal('0')
        for percentage in self.shares.values():
            if isinstance(percentage, int):
                decimal_sum += decimal.Decimal(str(percentage))
            else:
                decimal_sum += decimal.Decimal(str(percentage))

        if decimal_sum != decimal.Decimal('100'):
            raise ValueError(f"Percentages must sum up to exactly 100. Current sum: {decimal_sum}.")


# --- Expense and Group Management ---

@dataclass(frozen=True)
class Expense:
    """Represents a single shared expense.
    """
    description: str
    paid_by: str
    amount: int  # In cents
    split: Union[Equal, Exact, Percent]

    def __post_init__(self):
        if self.amount <= 0:
            raise ValueError("Expense amount must be positive.")
        # Further validation on split content can happen in Group.add_expense


@dataclass
class Group:
    """Manages members, expenses, and payments for a group.
    """
    members: List[str]
    expenses: List[tuple[Expense, Dict[str, int]]]
    payments: List[tuple[str, str, int]]

    def add_member(self, name: str) -> None:
        """Adds a new member to the group if they are not already present.
        """
        if name in self.members:
            raise ValueError(f"Member '{name}' is already in the group.")
        self.members.append(name)

    def add_payment(self, payer: str, payee: str, amount: int) -> None:
        """Records a direct payment between two members.
        """
        if payer not in self.members or payee not in self.members:
            raise ValueError("Payer or payee must be a member of the group.")
        if amount <= 0:
            raise ValueError("Payment amount must be positive.")
        self.payments.append((payer, payee, amount))

    def _calculate_equal_shares(self, amount: int, members_to_split: List[str]) -> Dict[str, int]:
        """Calculates shares for Equal split, handling remainder distribution alphabetically.
        """
        n = len(members_to_split)
        if n == 0:
            raise ValueError("Equal split list cannot be empty.")

        base_share = amount // n
        remainder = amount % n

        shares = {member: base_share for member in members_to_split}

        # Distribute remainder one by one to the first 'remainder' members alphabetically
        # Note: The requirement specifies distributing to the first participants in alphabetical order of name.
        # Since members_to_split is derived from Equal(members=...),
        # we sort them to find the alphabetical order for distribution.
        sorted_members = sorted(members_to_split)

        for i in range(remainder):
            member = sorted_members[i]
            shares[member] += 1

        return shares

    def _calculate_percent_shares(self, amount: int, split: Percent) -> Dict[str, int]:
        """Calculates shares for Percent split using floor and fractional part tie-breaking.
        """
        shares: Dict[str, int] = {}        
        remainders: List[tuple[float, str]] = [] # (fractional_part, member_name)

        # 1. Calculate floor shares
        for member, percentage_input in split.shares.items():
            # Ensure percentage is Decimal for accurate math
            if isinstance(percentage_input, str):
                percentage = decimal.Decimal(percentage_input)
            elif isinstance(percentage_input, int): 
                percentage = decimal.Decimal(str(percentage_input))
            else:
                percentage = percentage_input

            # Calculate exact value: amount * percentage / 100
            exact_value = decimal.Decimal(amount) * (percentage / decimal.Decimal('100'))

            # Floor share
            share_int = int(exact_value.to_integral_value(rounding=decimal.ROUND_FLOOR))
            shares[member] = share_int

            # Calculate remainder
            remainder_val = float(exact_value) - share_int
            remainders.append((remainder_val, member))

        # 2. Determine remaining amount
        total_assigned = sum(shares.values())
        remaining_amount = amount - total_assigned

        # 3. Distribute remainder based on largest fractional parts, ties broken alphabetically
        # Sort by remainder (descending), then by name (ascending for tie-break)
        remainders.sort(key=lambda x: (-x[0], x[1]))

        # Distribute 1 cent at a time
        for i in range(remaining_amount):
            if i < len(remainders):
                member = remainders[i][1]
                shares[member] += 1

        return shares

    def add_expense(self, expense: Expense) -> Dict[str, int]:
        """Computes shares for an expense and stores it.
        Returns the computed shares dictionary.
        """
        amount = expense.amount
        paid_by = expense.paid_by
        split = expense.split

        if paid_by not in self.members:
            raise ValueError("Expense payer must be a member of the group.")

        shares: Dict[str, int]

        if isinstance(split, Equal):
            if split.members is None:
                # Group-wide equal split
                members_to_split = self.members
            elif not all(m in self.members for m in split.members):
                raise ValueError("Equal split members not all in group.")

            shares = self._calculate_equal_shares(amount, split.members if split.members is not None else members_to_split)

        elif isinstance(split, Exact):
            # Validate exact shares against group members and sum
            if not all(member in self.members for member in split.shares):
                raise ValueError("All members listed in Exact split must be in the group.")

            total_shares = sum(split.shares.values())
            if total_shares != amount:
                 raise ValueError(f"Exact shares must sum to {amount} cents, but sum to {total_shares}.")
            shares = split.shares

        elif isinstance(split, Percent):
            # Percentage validation (summing to 100) is in __post_init__
            # Need to ensure all members in the split are in the group
            if not all(m in self.members for m in split.shares):
                 raise ValueError("All members listed in Percent split must be in the group.")
            shares = self._calculate_percent_shares(amount, split)

        else:
            raise TypeError("Unknown split type.")

        # Store the expense and its calculated shares
        self.expenses.append((expense, shares))

        return shares

# --- Group Loading Utility ---

def load_group(data: Dict) -> Group:
    """Builds a Group instance from a dictionary structure.
    """
    members_list = data.get('members', [])
    group = Group(members=list(members_list))

    # Process expenses
    for expense_data in data.get('expenses', []):
        description = expense_data['description']
        paid_by = expense_data['paid_by']
        amount_str = expense_data['amount']
        split_data = expense_data['split']

        amount_cents = parse_amount(amount_str)

        split: Union[Equal, Exact, Percent]
        if split_data['type'] == 'equal':
            members = split_data.get('members')
            split = Equal(members=members)
        elif split_data['type'] == 'exact':
            shares = split_data['shares']
            split = Exact(shares=shares)
        elif split_data['type'] == 'percent':
            shares = split_data['shares']
            split = Percent(shares=shares)
        else:
            raise ValueError(f"Unknown split type in expense: {split_data['type']}")

        expense = Expense(description, paid_by, amount_cents, split)
        # Note: add_expense handles the computation and storage into the group object
        group.add_expense(expense) # This adds the expense and returns shares, which we discard here as they are stored internally

    # Process payments
    for payment_data in data.get('payments', []):
        payer = payment_data['from']
        payee = payment_data['to']
        amount_str = payment_data['amount']
        amount_cents = parse_amount(amount_str)

        group.add_payment(payer, payee, amount_cents)

    return group
